import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { SearchSource } from '../types';

const SearchSection: React.FC = () => {
  const [query, setQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [answer, setAnswer] = useState('');
  const [sources, setSources] = useState<SearchSource[]>([]);

  const handleSearch = async () => {
    if (!query.trim() || isSearching) return;

    setIsSearching(true);
    setAnswer('');
    setSources([]);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: query,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      setAnswer(response.text || "No results found.");

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks) {
        const extractedSources: SearchSource[] = groundingChunks
          .map((chunk: any) => chunk.web)
          .filter((web: any) => !!web)
          .map((web: any) => ({
            title: web.title,
            uri: web.uri
          }));
        setSources(extractedSources);
      }
    } catch (error) {
      console.error('Search error:', error);
      setAnswer('Sorry, the search failed. Please try again later.');
    } finally {
      setIsSearching(false);
    }
  };

  return (
    <div className="space-y-8 pb-20">
      <header>
        <h2 className="text-3xl font-bold mb-2">Grounded Search</h2>
        <p className="text-slate-400">Real-time answers backed by the power of Google Search.</p>
      </header>

      <div className="glass p-6 rounded-3xl flex gap-3 border border-slate-800 focus-within:border-orange-500/50 transition-all">
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
          placeholder="What's happening in the tech world today?"
          className="flex-1 bg-transparent border-none focus:outline-none text-xl text-slate-100"
        />
        <button
          onClick={handleSearch}
          disabled={isSearching || !query.trim()}
          className="bg-orange-600 hover:bg-orange-500 disabled:opacity-50 text-white px-6 py-3 rounded-2xl font-bold transition-all shadow-lg shadow-orange-500/20"
        >
          {isSearching ? '...' : 'Search'}
        </button>
      </div>

      {(answer || isSearching) && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 glass p-8 rounded-3xl border border-slate-800 min-h-[300px]">
            <h3 className="text-xs font-bold text-orange-400 uppercase tracking-widest mb-6">AI Response</h3>
            {isSearching ? (
              <div className="space-y-4">
                <div className="h-4 bg-slate-800 rounded w-full animate-pulse"></div>
                <div className="h-4 bg-slate-800 rounded w-5/6 animate-pulse"></div>
                <div className="h-4 bg-slate-800 rounded w-4/6 animate-pulse"></div>
              </div>
            ) : (
              <div className="prose prose-invert max-w-none text-slate-200 leading-relaxed whitespace-pre-wrap">
                {answer}
              </div>
            )}
          </div>

          <div className="lg:col-span-1 space-y-4">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest px-2">Knowledge Sources</h3>
            {sources.length > 0 ? (
              <div className="space-y-3">
                {sources.map((src, i) => (
                  <a
                    key={i}
                    href={src.uri}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block glass p-4 rounded-2xl hover:bg-slate-800 transition-all border border-slate-800 group"
                  >
                    <div className="text-xs text-orange-400 mb-1 truncate">{new URL(src.uri).hostname}</div>
                    <div className="font-semibold text-slate-200 group-hover:text-white transition-colors line-clamp-2">{src.title}</div>
                  </a>
                ))}
              </div>
            ) : !isSearching ? (
              <div className="text-slate-600 text-sm px-2 italic">No sources cited for this query.</div>
            ) : (
              <div className="space-y-3">
                {[1, 2, 3].map(i => (
                  <div key={i} className="h-16 bg-slate-800/50 rounded-2xl animate-pulse"></div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

