      </button>
  );

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      if(!login(loginIdentifier, loginPassword)) {
          alert(language === 'en' ? 'Login failed.' : 'Login gagal.');
      }
  };

  const handleForgotSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      const userExists = users.find(u => u.email === resetEmail);
      if(userExists) {
          setResetStep(2);
          alert(language === 'en' ? `[SIMULATION] Verification code sent to ${resetEmail}. Code: 123456` : `[SIMULASI] Kode verifikasi dikirim ke ${resetEmail}. Kode: 123456`);
      } else {
          alert(language === 'en' ? 'Email not found.' : 'Email tidak ditemukan.');
      }
  };

  const handleTokenSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if(resetToken === '123456') {
          setResetStep(3);
      } else {
          alert(language === 'en' ? 'Invalid token.' : 'Kode tidak valid.');
      }
  };

  const handleResetPasswordFinal = (e: React.FormEvent) => {
      e.preventDefault();
      if(resetPassword(resetEmail, newPassword)) {
          alert(language === 'en' ? 'Success reset.' : 'Berhasil diatur ulang.');
          setIsForgotPassword(false);
          setResetStep(1);
      }
  };

  if (!isAdminOpen) return null;

  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-heritage-dark/95 backdrop-blur-md p-4 animate-fade-in">
