                  </div>
              </form>
            ) : (
              <div className="animate-fade-in">
                   {resetStep === 1 && (
                       <form onSubmit={handleForgotSubmit} className="space-y-5">
                           <div className="text-center"><h3 className="text-lg font-bold text-heritage-dark">{t.resetPass[language]}</h3></div>
                           <div className="relative group">
                               <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                               <input type="email" value={resetEmail} onChange={e=>setResetEmail(e.target.value)} className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg text-sm" placeholder="Email" required />
                           </div>
                           <button type="submit" className="w-full bg-heritage-dark text-white font-bold py-3 rounded-lg text-sm uppercase">{t.sendCode[language]}</button>
                       </form>
                   )}
                   <button onClick={() => { setIsForgotPassword(false); setResetStep(1); }} className="w-full mt-6 text-xs text-gray-400 uppercase tracking-wider">{t.backToLogin[language]}</button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
