      </div>

      {/* Split Preview Pane */}
      <div className="flex-1 bg-gray-200 flex flex-col h-full border-l border-gray-300 relative">
         <div className="bg-white border-b border-gray-300 p-3 flex justify-center items-center gap-4 shadow-sm z-10">
            <span className="text-xs font-bold uppercase text-gray-400 mr-2">{t.previewMode[language]}</span>
