              className={`w-full flex items-center gap-3 px-6 py-4 text-sm font-bold uppercase tracking-wider transition-colors ${
                activeSection === item.id ? 'bg-heritage-gold text-white' : 'text-gray-400 hover:bg-gray-800 hover:text-white'
