import { GoogleGenAI } from "@google/genai";

/**
 * Mak Itam - Sawahlunto Digital Heritage Guide.
 * Uses the latest Gemini 3 model to answer questions about Sawahlunto heritage.
 */
export const askHeritageGuide = async (question: string): Promise<string> => {
  // Always initialize inside the function to ensure up-to-date API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: question,
      config: {
        systemInstruction: `You are 'Mak Itam', a knowledgeable and friendly digital heritage guide for Sawahlunto City, West Sumatra, Indonesia. 

        Your knowledge base includes:
        1. The Ombilin Coal Mining Heritage of Sawahlunto (UNESCO World Heritage Site).
        2. Historical landmarks like Lobang Mbah Soero, Goedang Ransoem, and the Train Museum.
        3. Local culture, including Songket Silungkang and traditional cuisine.
        4. Practical travel advice for visiting Sawahlunto.

        Tone: Welcoming, educational, and respectful of the culture.
        Keep your answers concise (under 150 words) unless asked for a detailed history. 
        If the user asks about something unrelated to Sawahlunto or West Sumatra culture, politely steer them back to the topic.`,
        temperature: 0.7,
      }
    });

    // Access the text property directly from the response object
    return response.text || "I apologize, I couldn't find an answer in my archives right now.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to consult the archives. Please try again later.");
  }
};

/**
 * Generates translations for CMS content using Gemini.
 */
export const generateTranslation = async (text: string, targetLang: 'en' | 'id'): Promise<string> => {
    if (!text) return '';

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const target = targetLang === 'en' ? 'English' : 'Indonesian';

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Translate the following text to ${target}. Return ONLY the translated text, no preamble or quotes:

            "${text}"`,
        });
        // Access text property directly
        return response.text?.trim() || '';
    } catch (error) {
        console.error("Translation Error:", error);
        return text; // Fallback to original text on error
    }
};

