                <Lock className="w-7 h-7 text-heritage-gold" />
              </div>
              <h2 className="text-3xl font-serif font-bold text-heritage-dark mb-1">{t.adminPortal[language]}</h2>
              <p className="text-xs font-bold text-gray-400 uppercase tracking-[0.2em]">{t.cmsName[language]}</p>
            </div>
            {!isForgotPassword ? (
              <form onSubmit={handleLogin} className="space-y-6">
                  <div className="space-y-4">
