            { id: 'layout', label: t.layout[language], icon: Layers },
            { id: 'super_admin', label: t.superAdmin[language], icon: ShieldCheck, restricted: true },
            { id: 'navigation', label: t.navigation[language], icon: MenuIcon },
            { id: 'portals', label: t.portals[language], icon: ExternalLinkIcon },
            { id: 'hero_map', label: t.heroMap[language], icon: Map },
            { id: 'sections', label: t.sections[language], icon: FileText },
            { id: 'arts', label: t.arts[language], icon: Music },
            { id: 'news', label: t.news[language], icon: Info },
            { id: 'destinations', label: t.destinations[language], icon: Image },
            { id: 'tickets', label: t.tickets[language], icon: Ticket },
            { id: 'info', label: t.info[language], icon: Phone },
