import React, { useState, useEffect } from 'react';
import { useData } from '../contexts/DataContext';
import { Calendar, ArrowRight, Share2, ChevronRight, Image as ImageIcon } from 'lucide-react';

const NewsSection: React.FC = () => {
  const { news, language } = useData();
  const [selectedNews, setSelectedNews] = useState(news[0] || null);
  const [isTransitioning, setIsTransitioning] = useState(false);

  useEffect(() => {
    if (news.length > 0 && (!selectedNews || !news.find(n => n.id === selectedNews.id))) {
      setSelectedNews(news[0]);
    }
  }, [news, selectedNews]);

  const handleSelectNews = (item: typeof news[0]) => {
    if (selectedNews?.id === item.id) return;
    setIsTransitioning(true);
    setTimeout(() => {
      setSelectedNews(item);
      setIsTransitioning(false);
    }, 300);
  };

  if (news.length === 0) return null;

  return (
    <section id="news" className="py-24 bg-white scroll-mt-28 relative overflow-hidden">
      <div className="container mx-auto px-6">

        {/* Section Title */}
        <div className="mb-16 text-center lg:text-left">
            <div className="flex items-center justify-center lg:justify-start gap-3 mb-4">
                <div className="w-12 h-[2px] bg-heritage-gold"></div>
                <span className="text-heritage-gold uppercase tracking-[0.3em] font-sans text-xs font-bold">
                    {language === 'en' ? 'News & Archives' : 'Berita & Arsip'}
                </span>
            </div>
            <h2 className="font-serif text-4xl md:text-5xl font-bold text-heritage-dark leading-tight">
                {language === 'en' ? 'Latest Stories from Sawahlunto' : 'Kabar Terkini dari Sawahlunto'}
            </h2>
        </div>

        {/* 2-Column Museum Layout */}
        <div className="flex flex-col lg:flex-row gap-12 lg:gap-20 items-stretch">

            {/* Column 1: Photo Grid */}
            <div className="w-full lg:w-5/12 order-2 lg:order-1">
                <div className="grid grid-cols-2 gap-4 h-full content-start">
                    {news.map((item) => (
                        <button
                            key={item.id}
                            onClick={() => handleSelectNews(item)}
                            className={`group relative aspect-square overflow-hidden rounded-2xl transition-all duration-500 transform ${
                                selectedNews?.id === item.id 
                                ? 'ring-4 ring-heritage-gold ring-offset-4 scale-[0.98] z-10' 
                                : 'hover:scale-[1.02] opacity-60 hover:opacity-100 grayscale hover:grayscale-0'
                            }`}
                        >
                            <img 
                                src={item.imageUrl} 
                                alt={item.title[language]} 
                                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                            />
                            <div className={`absolute inset-0 bg-gradient-to-t from-heritage-dark/80 via-transparent to-transparent flex flex-col justify-end p-4 transition-opacity duration-300 ${
                                selectedNews?.id === item.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'
                            }`}>
                                <p className="text-white text-[10px] font-bold uppercase tracking-widest leading-tight line-clamp-2 text-left">
                                    {item.title[language]}
                                </p>
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* Column 2: Content Details */}
            <div className="w-full lg:w-7/12 order-1 lg:order-2">
                <div className={`bg-heritage-stone/40 rounded-[2.5rem] p-8 md:p-14 border border-white/50 shadow-sm min-h-full transition-all duration-300 ${isTransitioning ? 'opacity-0 translate-x-4' : 'opacity-100 translate-x-0'}`}>
                    {selectedNews && (
                        <div className="h-full flex flex-col">
                            <div className="flex items-center gap-3 mb-8">
                                <div className="bg-heritage-gold/20 text-heritage-gold px-4 py-1.5 rounded-full flex items-center gap-2">
                                    <Calendar className="w-4 h-4" />
                                    <span className="text-xs font-bold uppercase tracking-widest">
                                        {new Date(selectedNews.date).toLocaleDateString(language === 'en' ? 'en-US' : 'id-ID', { 
                                            year: 'numeric', month: 'long', day: 'numeric' 
                                        })}
                                    </span>
                                </div>
                            </div>
                            <h3 className="font-serif text-3xl md:text-5xl font-bold text-heritage-dark mb-8 leading-tight">
                                {selectedNews.title[language]}
                            </h3>
                            <div className="space-y-8 flex-1">
                                <p className="text-xl md:text-2xl font-serif text-heritage-brick font-medium italic border-l-4 border-heritage-gold/40 pl-6 leading-relaxed">
                                    {selectedNews.summary[language]}
                                </p>
                                <div className="text-gray-600 leading-relaxed text-base md:text-lg whitespace-pre-line font-sans">
                                    {selectedNews.content[language]}
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

        </div>
      </div>
    </section>
  );
};

