const AdminPanel: React.FC = () => {
  const { 
    language,
    isAdminOpen, setIsAdminOpen, isAuthenticated, currentUser, users, login, logout, addUser, updateUser, deleteUser, resetPassword,
    content, updateContent, updateTheme,
    navItems, addNavItem, updateNavItem, deleteNavItem, reorderNavItems,
    sectionOrder, reorderSections,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addTicket, updateTicket, deleteTicket,
    addHeroSlide, updateHeroSlide, deleteHeroSlide,
    addArtItem, updateArtItem, deleteArtItem,
    news, newsConfig, updateNewsConfig, addNews, updateNews, deleteNews,
    museums, addMuseum, updateMuseum, deleteMuseum,
    socialLinks, addSocialLink, updateSocialLink, deleteSocialLink,
    externalLinks, addExternalLink, updateExternalLink, deleteExternalLink
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [isForgotPassword, setIsForgotPassword] = useState(false);

  const [activeSection, setActiveSection] = useState<'general' | 'theme' | 'organization' | 'super_admin' | 'layout' | 'navigation' | 'hero_map' | 'sections' | 'arts' | 'news' | 'info' | 'tickets' | 'destinations' | 'portals'>('general');
  const [previewMode, setPreviewMode] = useState<'desktop' | 'tablet' | 'mobile'>('desktop');
  const [isTranslating, setIsTranslating] = useState(false);

  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [editingAttraction, setEditingAttraction] = useState<Attraction | null>(null);
  const [editingNews, setEditingNews] = useState<NewsItem | null>(null);
  const [editingMuseum, setEditingMuseum] = useState<MuseumItem | null>(null);
  const [editingSocial, setEditingSocial] = useState<SocialLink | null>(null);
  const [editingExternal, setEditingExternal] = useState<ExternalLink | null>(null);
  const [editingNav, setEditingNav] = useState<NavItem | null>(null);
  const [editingTicket, setEditingTicket] = useState<TicketItem | null>(null);
  const [editingHeroSlide, setEditingHeroSlide] = useState<HeroSlide | null>(null);
  const [editingArtItem, setEditingArtItem] = useState<ArtItem | null>(null);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  const handleDragStart = (e: React.DragEvent<HTMLDivElement>, position: number) => {
    dragItem.current = position;
  };

  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>, position: number) => {
    dragOverItem.current = position;
  };

  const handleNavDragEnd = (e: React.DragEvent<HTMLDivElement>) => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
        const copyListItems = [...navItems];
        const dragItemContent = copyListItems[dragItem.current];
        copyListItems.splice(dragItem.current, 1);
        copyListItems.splice(dragOverItem.current, 0, dragItemContent);
        dragItem.current = null;
        dragOverItem.current = null;
        reorderNavItems(copyListItems);
    }
  };

  const handleSectionDragEnd = (e: React.DragEvent<HTMLDivElement>) => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
        const copyListItems = [...sectionOrder];
        const dragItemContent = copyListItems[dragItem.current];
        copyListItems.splice(dragItem.current, 1);
        copyListItems.splice(dragOverItem.current, 0, dragItemContent);
        dragItem.current = null;
        dragOverItem.current = null;
        reorderSections(copyListItems);
    }
  };

  const handleTranslate = async (sourceText: string, section: keyof typeof content, field: string, targetField?: string) => {
      if(!sourceText) return;
      setIsTranslating(true);
      try {
          const translated = await generateTranslation(sourceText, 'en');
          if(section) {
             updateContent(section as any, field, translated, 'en');
          }
