        .btn-add:hover { background-color: var(--color-primary); color: white; }
        .btn-primary { background-color: var(--color-primary); color: white; font-weight: 700; padding: 0.75rem; border-radius: 0.375rem; }
        .btn-secondary { background-color: transparent; color: #6b7280; font-weight: 600; padding: 0.75rem 1.5rem; border-radius: 0.375rem; }
      `}</style>
    </div>
  );
};

