const quizData = [
  {
    id: '1',
    question: { en: 'In what year was coal first discovered in the Sawahlunto region?', id: 'Pada tahun berapakah batubara pertama kali ditemukan di wilayah Sawahlunto?' },
    options: [
      { en: '1858', id: '1858' },
