                    {language === 'en' 
                      ? 'Stay updated with our latest activities directly from our social media channels.' 
                      : 'Ikuti pembaruan kegiatan terbaru kami langsung dari kanal media sosial resmi.'}
                </p>
            </div>

            <div className="flex flex-col items-end gap-4">
                {/* Follow Button */}
                <a 
                    href="https://instagram.com" 
                    target="_blank" 
                    className="flex items-center gap-2 bg-gradient-to-tr from-[#F58529] via-[#DD2A7B] to-[#8134AF] text-white px-6 py-2.5 rounded-full text-xs font-bold uppercase tracking-widest shadow-lg hover:scale-105 transition-transform"
                >
                    <Instagram className="w-4 h-4" />
                    Follow @dinaskebudayaan_swl
                </a>

                {/* Navigation Buttons (Desktop) */}
                <div className="hidden md:flex gap-3">
                    <button 
                        onClick={prevSlide}
                        disabled={currentIndex === 0}
                        className={`p-3 rounded-full border-2 transition-all ${
                            currentIndex === 0 
                            ? 'border-gray-100 text-gray-200 cursor-not-allowed' 
                            : 'border-heritage-dark text-heritage-dark hover:bg-heritage-dark hover:text-white'
                        }`}
                    >
                        <ChevronLeft className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={nextSlide}
                        disabled={currentIndex >= maxIndex}
                        className={`p-3 rounded-full border-2 transition-all ${
                            currentIndex >= maxIndex 
                            ? 'border-gray-100 text-gray-200 cursor-not-allowed' 
                            : 'border-heritage-dark text-heritage-dark hover:bg-heritage-dark hover:text-white'
                        }`}
                    >
                        <ChevronRight className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>

        {/* Slider Container */}
        <div className="relative group">
            <div className="overflow-hidden">
                <div 
                    ref={containerRef}
                    className="flex transition-transform duration-700 ease-[cubic-bezier(0.25,1,0.5,1)]"
                    style={{ 
