const LivePreview: React.FC = () => {
    const { sectionOrder } = useData();

    const sectionComponents: Record<string, React.ReactNode> = {
      hero: <Hero key="hero" />,
      map: <MuseumMap key="map" />,
      portals: <ExternalPortals key="portals" />,
      heritage: <HeritageMain key="heritage" />,
      arts: <ArtsSection key="arts" />,
      news: <NewsSection key="news" />,
      attractions: <Attractions key="attractions" />,
      info: <InfoSection key="info" />
    };

    return (
        <div className="bg-heritage-stone h-full w-full overflow-y-auto overflow-x-hidden shadow-2xl bg-white scroll-smooth relative">
            <Navbar />
            {sectionOrder.map(key => sectionComponents[key])}
            <Footer />
        </div>
    );
};

const AdminPanel: React.FC = () => {
  const { 
    language,
    isAdminOpen, setIsAdminOpen, isAuthenticated, currentUser, users, login, logout, addUser, updateUser, deleteUser, resetPassword,
    content, updateContent, updateTheme,
    navItems, addNavItem, updateNavItem, deleteNavItem, reorderNavItems,
    sectionOrder, reorderSections,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addTicket, updateTicket, deleteTicket,
    addHeroSlide, updateHeroSlide, deleteHeroSlide,
    addArtItem, updateArtItem, deleteArtItem,
    news, newsConfig, updateNewsConfig, addNews, updateNews, deleteNews,
    museums, addMuseum, updateMuseum, deleteMuseum,
    socialLinks, addSocialLink, updateSocialLink, deleteSocialLink,
    externalLinks, addExternalLink, updateExternalLink, deleteExternalLink
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [isForgotPassword, setIsForgotPassword] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [resetStep, setResetStep] = useState(1);
  const [resetToken, setResetToken] = useState('');
  const [newPassword, setNewPassword] = useState('');

  const [activeSection, setActiveSection] = useState<'general' | 'theme' | 'organization' | 'super_admin' | 'layout' | 'navigation' | 'hero_map' | 'sections' | 'arts' | 'news' | 'info' | 'tickets' | 'destinations' | 'portals'>('general');
  const [previewMode, setPreviewMode] = useState<'desktop' | 'tablet' | 'mobile'>('desktop');
  const [isTranslating, setIsTranslating] = useState(false);

  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [editingAttraction, setEditingAttraction] = useState<Attraction | null>(null);
  const [editingNews, setEditingNews] = useState<NewsItem | null>(null);
  const [editingMuseum, setEditingMuseum] = useState<MuseumItem | null>(null);
  const [editingSocial, setEditingSocial] = useState<SocialLink | null>(null);
  const [editingExternal, setEditingExternal] = useState<ExternalLink | null>(null);
  const [editingNav, setEditingNav] = useState<NavItem | null>(null);
  const [editingTicket, setEditingTicket] = useState<TicketItem | null>(null);
  const [editingHeroSlide, setEditingHeroSlide] = useState<HeroSlide | null>(null);
  const [editingArtItem, setEditingArtItem] = useState<ArtItem | null>(null);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  const handleDragStart = (e: React.DragEvent<HTMLDivElement>, position: number) => {
    dragItem.current = position;
  };

  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>, position: number) => {
    dragOverItem.current = position;
  };

  const handleNavDragEnd = (e: React.DragEvent<HTMLDivElement>) => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
        const copyListItems = [...navItems];
        const dragItemContent = copyListItems[dragItem.current];
        copyListItems.splice(dragItem.current, 1);
        copyListItems.splice(dragOverItem.current, 0, dragItemContent);
        dragItem.current = null;
        dragOverItem.current = null;
        reorderNavItems(copyListItems);
    }
  };

  const handleSectionDragEnd = (e: React.DragEvent<HTMLDivElement>) => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
        const copyListItems = [...sectionOrder];
        const dragItemContent = copyListItems[dragItem.current];
        copyListItems.splice(dragItem.current, 1);
        copyListItems.splice(dragOverItem.current, 0, dragItemContent);
        dragItem.current = null;
        dragOverItem.current = null;
        reorderSections(copyListItems);
    }
  };

  const handleTranslate = async (sourceText: string, section: keyof typeof content, field: string, targetField?: string) => {
      if(!sourceText) return;
      setIsTranslating(true);
      try {
          const translated = await generateTranslation(sourceText, 'en');
          if(section) {
             updateContent(section as any, field, translated, 'en');
          }
      } catch (e) {
          alert('Translation failed. Please try again.');
      } finally {
          setIsTranslating(false);
      }
  };

  const AutoTranslateButton = ({ sourceText, onClick }: { sourceText: string, onClick: () => void }) => (
      <button 
        type="button"
        onClick={onClick}
        disabled={isTranslating || !sourceText}
        className="text-[10px] uppercase font-bold text-heritage-gold flex items-center gap-1 hover:text-heritage-brick transition-colors disabled:opacity-50 mt-1"
      >
        {isTranslating ? <RefreshCw className="w-3 h-3 animate-spin" /> : <Sparkles className="w-3 h-3" />}
        {isTranslating ? t.translating[language] : t.autoTranslate[language]}
      </button>
  );

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      if(!login(loginIdentifier, loginPassword)) {
          alert(language === 'en' ? 'Login failed.' : 'Login gagal.');
      }
  };

  if (!isAdminOpen) return null;

  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-heritage-dark/95 backdrop-blur-md p-4 animate-fade-in">
        <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl relative overflow-hidden animate-scale-in border border-white/10">
          <div className="h-1.5 w-full bg-gradient-to-r from-heritage-dark via-heritage-gold to-heritage-dark"></div>
          <button onClick={() => setIsAdminOpen(false)} className="absolute top-4 right-4 text-gray-400 hover:text-heritage-brick transition-colors p-2 rounded-full hover:bg-gray-100">
             <X className="w-5 h-5" />
          </button>
          <div className="p-8 pt-10">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-heritage-gold/10 rounded-full flex items-center justify-center mx-auto mb-4 border border-heritage-gold/20 shadow-inner">
                <Lock className="w-7 h-7 text-heritage-gold" />
              </div>
              <h2 className="text-3xl font-serif font-bold text-heritage-dark mb-1">{t.adminPortal[language]}</h2>
              <p className="text-xs font-bold text-gray-400 uppercase tracking-[0.2em]">{t.cmsName[language]}</p>
            </div>
            {!isForgotPassword ? (
              <form onSubmit={handleLogin} className="space-y-6">
                  <div className="space-y-4">
                      <div className="relative group">
                          <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-heritage-gold" />
                          <input type="text" value={loginIdentifier} onChange={(e) => setLoginIdentifier(e.target.value)} className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:border-heritage-gold focus:ring-1 focus:ring-heritage-gold text-sm" placeholder={t.usernamePlaceholder[language]} required />
                      </div>
                      <div className="relative group">
                          <Key className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-heritage-gold" />
                          <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:border-heritage-gold focus:ring-1 focus:ring-heritage-gold text-sm" placeholder={t.passwordPlaceholder[language]} required />
                      </div>
                  </div>
                  <button type="submit" className="w-full bg-heritage-dark text-white font-bold py-3.5 rounded-lg hover:bg-heritage-gold transition-all shadow-lg uppercase tracking-widest text-xs flex items-center justify-center gap-2 group">
                    <span>{t.signIn[language]}</span>
                    <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                  </button>
              </form>
            ) : null}
          </div>
        </div>
      </div>
    );
  }

  const handleAttrSave = (e: React.FormEvent) => { e.preventDefault(); if(editingAttraction) { attractions.find(a=>a.id===editingAttraction.id) ? updateAttraction(editingAttraction.id, editingAttraction) : addAttraction(editingAttraction); setEditingAttraction(null); }};
  const handleNewsSave = (e: React.FormEvent) => { e.preventDefault(); if(editingNews) { news.find(n=>n.id===editingNews.id) ? updateNews(editingNews.id, editingNews) : addNews(editingNews); setEditingNews(null); }};
  const handleMuseumSave = (e: React.FormEvent) => { e.preventDefault(); if(editingMuseum) { museums.find(m=>m.id===editingMuseum.id) ? updateMuseum(editingMuseum.id, editingMuseum) : addMuseum(editingMuseum); setEditingMuseum(null); }};
  const handleSocialSave = (e: React.FormEvent) => { e.preventDefault(); if(editingSocial) { socialLinks.find(s=>s.id===editingSocial.id) ? updateSocialLink(editingSocial.id, editingSocial) : addSocialLink(editingSocial); setEditingSocial(null); }};
  const handleExternalSave = (e: React.FormEvent) => { e.preventDefault(); if(editingExternal) { externalLinks.find(l=>l.id===editingExternal.id) ? updateExternalLink(editingExternal.id, editingExternal) : addExternalLink(editingExternal); setEditingExternal(null); }};
  const handleNavSave = (e: React.FormEvent) => { e.preventDefault(); if(editingNav) { navItems.find(i=>i.id===editingNav.id) ? updateNavItem(editingNav.id, editingNav) : addNavItem(editingNav); setEditingNav(null); }};
  const handleTicketSave = (e: React.FormEvent) => { e.preventDefault(); if(editingTicket) { content.tickets.items.find(i=>i.id===editingTicket.id) ? updateTicket(editingTicket.id, editingTicket) : addTicket(editingTicket); setEditingTicket(null); }};
  const handleHeroSlideSave = (e: React.FormEvent) => { e.preventDefault(); if (editingHeroSlide) { content.hero.slides.find(s => s.id === editingHeroSlide.id) ? updateHeroSlide(editingHeroSlide.id, editingHeroSlide) : addHeroSlide(editingHeroSlide); setEditingHeroSlide(null); } };
  const handleArtItemSave = (e: React.FormEvent) => { e.preventDefault(); if (editingArtItem) { content.arts.items.find(a => a.id === editingArtItem.id) ? updateArtItem(editingArtItem.id, editingArtItem) : addArtItem(editingArtItem); setEditingArtItem(null); } };
  const handleUserSave = (e: React.FormEvent) => { e.preventDefault(); if(editingUser) { users.find(u => u.id === editingUser.id) ? updateUser(editingUser.id, editingUser) : addUser(editingUser); setEditingUser(null); } };

  return (
    <div className="fixed inset-0 z-[100] bg-gray-100 flex font-sans overflow-hidden">

      {/* Sidebar */}
      <div className="w-64 bg-heritage-dark text-white flex flex-col shrink-0 h-full border-r border-gray-700">
        <div className="p-6 border-b border-gray-700">
          <h1 className="font-display font-bold text-xl tracking-wider text-white">CMS PANEL</h1>
          <div className="flex items-center gap-2 mt-2">
            <div className="w-2 h-2 rounded-full bg-green-500"></div>
            <p className="text-xs text-gray-300 truncate">{currentUser?.fullName}</p>
          </div>
        </div>
        <nav className="flex-1 overflow-y-auto py-4">
          {[
            { id: 'general', label: t.general[language], icon: Globe },
            { id: 'theme', label: t.theme[language], icon: Palette },
            { id: 'organization', label: t.organization[language], icon: Users },
            { id: 'layout', label: t.layout[language], icon: Layers },
            { id: 'super_admin', label: t.superAdmin[language], icon: ShieldCheck, restricted: true },
            { id: 'navigation', label: t.navigation[language], icon: MenuIcon },
            { id: 'portals', label: t.portals[language], icon: ExternalLinkIcon },
            { id: 'hero_map', label: t.heroMap[language], icon: Map },
            { id: 'sections', label: t.sections[language], icon: FileText },
            { id: 'arts', label: t.arts[language], icon: Music },
            { id: 'news', label: t.news[language], icon: Instagram },
            { id: 'destinations', label: t.destinations[language], icon: Image },
            { id: 'tickets', label: t.tickets[language], icon: Ticket },
            { id: 'info', label: t.info[language], icon: Phone },
          ]
          .filter(item => !item.restricted || currentUser?.role === 'super_admin')
          .map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveSection(item.id as any)}
              className={`w-full flex items-center gap-3 px-6 py-4 text-sm font-bold uppercase tracking-wider transition-colors ${
                activeSection === item.id ? 'bg-heritage-gold text-white' : 'text-gray-400 hover:bg-gray-800 hover:text-white'
              }`}
            >
              <item.icon className="w-4 h-4" />
              {item.label}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-gray-700">
          <button onClick={logout} className="w-full flex items-center justify-center gap-2 py-3 rounded bg-red-600/20 text-red-400 hover:bg-red-600 hover:text-white transition-colors text-sm font-bold uppercase">
            <LogOut className="w-4 h-4" /> {t.logout[language]}
          </button>
          <button onClick={() => setIsAdminOpen(false)} className="w-full mt-2 text-gray-500 hover:text-white text-xs text-center py-2">
            {t.closePanel[language]}
          </button>
        </div>
      </div>

      {/* Editor Content Area */}
      <div className="flex-1 flex flex-col h-full overflow-hidden bg-gray-100 w-1/3 min-w-[500px]">
        <div className="flex-1 overflow-y-auto p-8">
            <div className="flex justify-between items-end mb-8 border-b border-gray-200 pb-4">
                <div>
                <h2 className="text-2xl font-serif font-bold text-heritage-dark capitalize">{activeSection.replace('_', ' ')}</h2>
                <p className="text-gray-500 mt-1 text-sm">{t.editContent[language]}</p>
                </div>
            </div>

            <div className="space-y-6">

                {activeSection === 'general' && (
                    <div className="space-y-8 animate-fade-in-up">
                        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
                            <h3 className="font-bold text-lg text-heritage-dark mb-4 border-l-4 border-heritage-gold pl-3">{t.siteIdentity[language]}</h3>
                            <div className="grid grid-cols-1 gap-6">
                                <div><label className="input-label">Site Name</label><input type="text" value={content.branding.siteName} onChange={(e) => updateContent('branding', 'siteName', e.target.value)} className="input-field" /></div>
                                <div><label className="input-label">Subtitle (Tagline)</label><input type="text" value={content.branding.subTitle} onChange={(e) => updateContent('branding', 'subTitle', e.target.value)} className="input-field" /></div>
                            </div>
                        </div>
                        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
                            <div className="flex justify-between items-center mb-4">
                                <h3 className="font-bold text-lg text-heritage-dark border-l-4 border-heritage-gold pl-3">{t.socialLinks[language]}</h3>
                                <button onClick={() => setEditingSocial({ id: Date.now().toString(), platform: 'Instagram', url: '' })} className="btn-add"><Plus className="w-4 h-4" /> Add</button>
                            </div>
                            {editingSocial && (
                                <form onSubmit={handleSocialSave} className="mb-6 p-4 bg-gray-50 rounded border border-gray-200 space-y-4">
                                    <div className="grid grid-cols-2 gap-4">
                                        <div><label className="input-label">Platform</label>
                                            <select value={editingSocial.platform} onChange={e => setEditingSocial({...editingSocial, platform: e.target.value as any})} className="input-field">
                                                {['Instagram', 'Facebook', 'Twitter', 'Youtube', 'TikTok', 'Website', 'Email', 'Phone'].map(p => <option key={p} value={p}>{p}</option>)}
                                            </select>
                                        </div>
                                        <div><label className="input-label">URL / ID</label><input type="text" value={editingSocial.url} onChange={e => setEditingSocial({...editingSocial, url: e.target.value})} className="input-field" /></div>
                                    </div>
                                    <div className="flex gap-2"><button type="submit" className="btn-primary flex-1">Save</button><button type="button" onClick={() => setEditingSocial(null)} className="btn-secondary">Cancel</button></div>
                                </form>
                            )}
                            <div className="space-y-2">
                                {socialLinks.map(link => (
                                    <div key={link.id} className="flex justify-between items-center p-3 bg-gray-50 rounded border border-gray-100">
                                        <div className="flex items-center gap-3">
                                            <span className="font-bold text-sm text-heritage-dark">{link.platform}:</span>
                                            <span className="text-xs text-gray-500 truncate max-w-[200px]">{link.url}</span>
                                        </div>
                                        <div className="flex gap-2">
                                            <button onClick={() => setEditingSocial(link)} className="text-blue-500 p-1"><Edit2 className="w-4 h-4" /></button>
                                            <button onClick={() => deleteSocialLink(link.id)} className="text-red-500 p-1"><Trash2 className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}

                {activeSection === 'theme' && (
                    <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 animate-fade-in-up">
                        <h3 className="font-bold text-lg text-heritage-dark mb-6 border-l-4 border-heritage-gold pl-3">{t.themeSettings[language]}</h3>
                        <div className="grid grid-cols-1 gap-6">
                            {[
                                { k: 'primary', l: t.primaryColor[language] },
                                { k: 'secondary', l: t.secondaryColor[language] },
                                { k: 'background', l: t.bgColor[language] },
                                { k: 'dark', l: t.darkColor[language] }
                            ].map(({ k, l }) => (
                                <div key={k} className="space-y-2">
                                    <label className="input-label">{l}</label>
                                    <div className="flex gap-3 items-center">
                                        <input type="color" value={(content.theme as any)[k]} onChange={(e) => updateTheme({...content.theme, [k]: e.target.value})} className="w-12 h-12 rounded cursor-pointer border-none p-0" />
                                        <input type="text" value={(content.theme as any)[k]} onChange={(e) => updateTheme({...content.theme, [k]: e.target.value})} className="input-field font-mono" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
