import React, { useState, useRef, useEffect } from 'react';
import { useData } from '../contexts/DataContext';
import { Calendar, ChevronLeft, ChevronRight, ArrowRight, Clock } from 'lucide-react';

const NewsSection: React.FC = () => {
  const { news, language, setSelectedNewsId } = useData();
  const [currentIndex, setCurrentIndex] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // Responsiveness: Determine how many items to show
  const [itemsPerPage, setItemsPerPage] = useState(3);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 640) setItemsPerPage(1);
      else if (window.innerWidth < 1024) setItemsPerPage(2);
      else setItemsPerPage(3);
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const maxIndex = Math.max(0, news.length - itemsPerPage);

  const nextSlide = () => {
    setCurrentIndex((prev) => Math.min(prev + 1, maxIndex));
  };

  const prevSlide = () => {
    setCurrentIndex((prev) => Math.max(prev - 1, 0));
  };

  if (news.length === 0) return null;

  return (
    <section id="news" className="py-24 bg-white scroll-mt-28 relative overflow-hidden">
      <div className="container mx-auto px-6">

        {/* Section Header */}
        <div className="flex flex-col md:flex-row justify-between items-end mb-12 gap-6">
            <div className="max-w-2xl">
                <div className="flex items-center gap-3 mb-4">
                    <div className="w-12 h-[2px] bg-heritage-gold"></div>
                    <span className="text-heritage-gold uppercase tracking-[0.3em] font-sans text-xs font-bold">
                        {language === 'en' ? 'News & Archives' : 'Kabar Terkini'}
                    </span>
                </div>
                <h2 className="font-serif text-4xl md:text-5xl font-bold text-heritage-dark leading-tight">
                    {language === 'en' ? 'Stories from Sawahlunto' : 'Cerita dari Sawahlunto'}
                </h2>
            </div>

            {/* Navigation Buttons (Desktop) */}
            <div className="hidden md:flex gap-3">
                <button 
                    onClick={prevSlide}
                    disabled={currentIndex === 0}
                    className={`p-4 rounded-full border-2 transition-all ${
                        currentIndex === 0 
                        ? 'border-gray-100 text-gray-300 cursor-not-allowed' 
                        : 'border-heritage-dark text-heritage-dark hover:bg-heritage-dark hover:text-white'
                    }`}
                >
                    <ChevronLeft className="w-6 h-6" />
                </button>
                <button 
                    onClick={nextSlide}
                    disabled={currentIndex >= maxIndex}
                    className={`p-4 rounded-full border-2 transition-all ${
                        currentIndex >= maxIndex 
                        ? 'border-gray-100 text-gray-300 cursor-not-allowed' 
                        : 'border-heritage-dark text-heritage-dark hover:bg-heritage-dark hover:text-white'
                    }`}
                >
                    <ChevronRight className="w-6 h-6" />
                </button>
            </div>
        </div>

        {/* Slider Container */}
        <div className="relative group">
            <div className="overflow-hidden">
                <div 
                    ref={containerRef}
                    className="flex transition-transform duration-700 ease-[cubic-bezier(0.25,1,0.5,1)]"
                    style={{ 
                        transform: `translateX(-${currentIndex * (100 / itemsPerPage)}%)`
                    }}
                >
                    {news.map((item) => (
                        <div 
                            key={item.id} 
                            className="px-3 shrink-0"
                            style={{ width: `${100 / itemsPerPage}%` }}
                        >
                            <div 
                                onClick={() => setSelectedNewsId(item.id)}
                                className="bg-white rounded-2xl overflow-hidden border border-gray-100 group/card hover:shadow-xl transition-all duration-500 h-full flex flex-col cursor-pointer"
                            >
                                {/* Image Container */}
                                <div className="relative h-64 overflow-hidden">
                                    <img 
                                        src={item.imageUrl} 
                                        alt={item.title[language]} 
                                        className="w-full h-full object-cover transition-transform duration-1000 group-hover/card:scale-110"
                                    />
                                    <div className="absolute top-4 left-4 bg-white/90 backdrop-blur px-3 py-1 rounded shadow-sm">
                                        <div className="flex items-center gap-2">
                                            <Calendar className="w-3 h-3 text-heritage-gold" />
                                            <span className="text-[10px] font-bold text-heritage-dark uppercase tracking-widest">
                                                {new Date(item.date).toLocaleDateString(language === 'en' ? 'en-US' : 'id-ID', { 
                                                    month: 'short', day: 'numeric' 
                                                })}
                                            </span>
                                        </div>
                                    </div>
                                </div>

                                {/* Content Container */}
                                <div className="p-8 flex-1 flex flex-col">
                                    <div className="flex items-center gap-2 mb-4 text-heritage-gold">
                                        <Clock className="w-3 h-3" />
                                        <span className="text-[10px] uppercase font-bold tracking-widest">
                                            {language === 'en' ? 'Latest News' : 'Berita Utama'}
                                        </span>
                                    </div>
                                    <h3 className="font-serif text-xl font-bold text-heritage-dark mb-4 group-hover/card:text-heritage-gold transition-colors line-clamp-2">
                                        {item.title[language]}
                                    </h3>
                                    <p className="text-gray-500 text-sm leading-relaxed mb-8 line-clamp-3">
                                        {item.summary[language]}
                                    </p>
                                    <div className="mt-auto pt-6 border-t border-gray-50 flex items-center justify-between">
                                        <button className="text-xs font-black uppercase tracking-widest text-heritage-dark hover:text-heritage-gold flex items-center gap-2 group/btn">
                                            {language === 'en' ? 'Read Full Story' : 'Baca Selengkapnya'}
                                            <ArrowRight className="w-4 h-4 transition-transform group-hover/btn:translate-x-1" />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Mobile Navigation Arrows */}
            <div className="flex md:hidden justify-center gap-4 mt-8">
                <button 
                    onClick={prevSlide}
                    disabled={currentIndex === 0}
                    className="p-3 rounded-full border border-gray-200 bg-white"
                >
                    <ChevronLeft className="w-5 h-5" />
                </button>
                <button 
                    onClick={nextSlide}
                    disabled={currentIndex >= maxIndex}
                    className="p-3 rounded-full border border-gray-200 bg-white"
                >
                    <ChevronRight className="w-5 h-5" />
                </button>
            </div>
        </div>

        {/* Progress Dots */}
        <div className="mt-12 flex justify-center gap-2">
            {Array.from({ length: maxIndex + 1 }).map((_, idx) => (
                <button
                    key={idx}
                    onClick={() => setCurrentIndex(idx)}
                    className={`transition-all duration-300 rounded-full h-1.5 ${
                        currentIndex === idx ? 'w-8 bg-heritage-gold' : 'w-2 bg-gray-200 hover:bg-gray-300'
                    }`}
                />
            ))}
        </div>
      </div>
    </section>
  );
};

export default NewsSection;

import React, { useEffect, useState } from 'react';
import { useData } from '../contexts/DataContext';
import { X, ArrowLeft, Calendar, Share2, Facebook, Twitter, Link as LinkIcon, MessageCircle } from 'lucide-react';

const NewsDetail: React.FC = () => {
  const { news, selectedNewsId, setSelectedNewsId, language } = useData();
  const [isScrolled, setIsScrolled] = useState(false);

  const selectedNews = news.find(item => item.id === selectedNewsId);

  useEffect(() => {
    if (selectedNewsId) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [selectedNewsId]);

  if (!selectedNewsId || !selectedNews) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-white overflow-y-auto animate-slide-up">
      {/* Dynamic Top Bar */}
      <div className={`fixed top-0 left-0 w-full z-20 transition-all duration-300 px-6 py-4 flex justify-between items-center ${
        isScrolled ? 'bg-white shadow-md border-b border-gray-100' : 'bg-transparent'
      }`}>
        <button 
          onClick={() => setSelectedNewsId(null)}
          className={`flex items-center gap-2 px-4 py-2 rounded-full font-bold uppercase tracking-widest text-[10px] transition-all ${
            isScrolled ? 'bg-heritage-dark text-white' : 'bg-white/90 backdrop-blur text-heritage-dark shadow-xl'
          }`}
        >
          <ArrowLeft className="w-4 h-4" />
          {language === 'en' ? 'Back' : 'Kembali'}
        </button>

        <div className="flex gap-2">
            <button className={`p-2 rounded-full transition-all ${isScrolled ? 'bg-gray-100 text-heritage-dark' : 'bg-white/90 backdrop-blur text-heritage-dark shadow-xl'}`}>
                <Share2 className="w-4 h-4" />
            </button>
            <button 
                onClick={() => setSelectedNewsId(null)}
                className={`p-2 rounded-full transition-all ${isScrolled ? 'bg-heritage-dark text-white' : 'bg-white/90 backdrop-blur text-heritage-dark shadow-xl'}`}
            >
                <X className="w-4 h-4" />
            </button>
        </div>
      </div>

      <div onScroll={(e) => setIsScrolled(e.currentTarget.scrollTop > 100)}>
        {/* Article Hero Header */}
        <div className="relative h-[60vh] md:h-[70vh] w-full overflow-hidden">
          <img 
            src={selectedNews.imageUrl} 
