  updateNews: (id: string, item: NewsItem) => void;
  deleteNews: (id: string) => void;

  museums: MuseumItem[];
  addMuseum: (item: MuseumItem) => void;
  updateMuseum: (id: string, updated: MuseumItem) => void;
  deleteMuseum: (id: string) => void;

  socialLinks: SocialLink[];
