  const handleSocialSave = (e: React.FormEvent) => { e.preventDefault(); if(editingSocial) { socialLinks.find(s=>s.id===editingSocial.id) ? updateSocialLink(editingSocial.id, editingSocial) : addSocialLink(editingSocial); setEditingSocial(null); }};
  const handleExternalSave = (e: React.FormEvent) => { e.preventDefault(); if(editingExternal) { externalLinks.find(l=>l.id===editingExternal.id) ? updateExternalLink(editingExternal.id, editingExternal) : addExternalLink(editingExternal); setEditingExternal(null); }};
  const handleNavSave = (e: React.FormEvent) => { e.preventDefault(); if(editingNav) { navItems.find(i=>i.id===editingNav.id) ? updateNavItem(editingNav.id, editingNav) : addNavItem(editingNav); setEditingNav(null); }};
  const handleTicketSave = (e: React.FormEvent) => { e.preventDefault(); if(editingTicket) { content.tickets.items.find(i=>i.id===editingTicket.id) ? updateTicket(editingTicket.id, editingTicket) : addTicket(editingTicket); setEditingTicket(null); }};
  const handleHeroSlideSave = (e: React.FormEvent) => { e.preventDefault(); if (editingHeroSlide) { content.hero.slides.find(s => s.id === editingHeroSlide.id) ? updateHeroSlide(editingHeroSlide.id, editingHeroSlide) : addHeroSlide(editingHeroSlide); setEditingHeroSlide(null); } };
  const handleArtItemSave = (e: React.FormEvent) => { e.preventDefault(); if (editingArtItem) { content.arts.items.find(a => a.id === editingArtItem.id) ? updateArtItem(editingArtItem.id, editingArtItem) : addArtItem(editingArtItem); setEditingArtItem(null); } };
  const handleUserSave = (e: React.FormEvent) => { e.preventDefault(); if(editingUser) { users.find(u => u.id === editingUser.id) ? updateUser(editingUser.id, editingUser) : addUser(editingUser); setEditingUser(null); } };

