                            <div><label className="input-label">Full Detail Content (ID)</label><textarea required value={editingArtItem.content?.id || ''} onChange={e => setEditingArtItem({...editingArtItem, content: { en: editingArtItem.content?.en || '', id: e.target.value}})} className="input-field h-40" /></div>

                            {/* Multi-Image Art */}
