                            <div><label className="input-label">Short Description (ID)</label><textarea required value={editingArtItem.description.id} onChange={e => setEditingArtItem({...editingArtItem, description: {...editingArtItem.description, id: e.target.value}})} className="input-field h-24" /></div>
                            <div><label className="input-label">Detailed Content (ID)</label><textarea required value={editingArtItem.content?.id || ''} onChange={e => setEditingArtItem({...editingArtItem, content: { en: '', id: e.target.value}})} className="input-field h-40" /></div>

                            <div className="p-4 bg-white rounded border border-gray-200 space-y-4">
                                <label className="input-label mb-0 font-bold">Gallery Photos</label>
                                <div><label className="input-label text-[9px]">Main Image</label><input required type="text" value={editingArtItem.imageUrl} onChange={e => setEditingArtItem({...editingArtItem, imageUrl: e.target.value})} className="input-field" /></div>
                                <button type="button" onClick={() => setEditingArtItem({...editingArtItem, imageUrls: [...(editingArtItem.imageUrls || []), '']})} className="text-xs font-bold text-heritage-gold flex items-center gap-1"><PlusCircle className="w-3 h-3"/> Add More Images</button>
                                {(editingArtItem.imageUrls || []).map((url, idx) => (
                                    <div key={idx} className="flex gap-2">
                                        <input type="text" value={url} onChange={e => { const newUrls = [...(editingArtItem.imageUrls || [])]; newUrls[idx] = e.target.value; setEditingArtItem({...editingArtItem, imageUrls: newUrls}); }} className="input-field" />
                                        <button type="button" onClick={() => { setEditingArtItem({...editingArtItem, imageUrls: (editingArtItem.imageUrls || []).filter((_, i) => i !== idx)}); }} className="text-red-500"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-2"><button type="submit" className="btn-primary flex-1">Save Item</button><button type="button" onClick={() => setEditingArtItem(null)} className="btn-secondary">Cancel</button></div>
                        </form>
                    ) : (
