  const galleryImages = selectedNews?.imageUrls || [];
  const images = [selectedNews?.imageUrl || '', ...galleryImages].filter(img => img !== '');

  useEffect(() => {
    if (selectedNewsId) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
