  const [selectedNewsId, setSelectedNewsId] = useState<string | null>(null);
  const [selectedArtId, setSelectedArtId] = useState<string | null>(null);
  const [content, setContent] = useState<SiteContent>(defaultContent);
  const [navItems, setNavItems] = useState<NavItem[]>(defaultNavItems);
  const [activeHeritageTab, setActiveHeritageTab] = useState<'tangible' | 'intangible'>('tangible');
  const [activeInfoTab, setActiveInfoTab] = useState<'tickets' | 'vision' | 'org' | 'map'>('tickets');
  const [sectionOrder, setSectionOrder] = useState<SectionKey[]>(['hero', 'map', 'portals', 'heritage', 'arts', 'news', 'attractions', 'info']);
  const [attractions, setAttractions] = useState<Attraction[]>([]);
  const [localNews, setLocalNews] = useState<NewsItem[]>([]);
  const [news, setNews] = useState<NewsItem[]>([]);
  const [newsConfig, setNewsConfig] = useState<NewsConfig>({ source: 'local', sheetUrl: '' });
  const [museums, setMuseums] = useState<MuseumItem[]>([]);
  const [socialLinks, setSocialLinks] = useState<SocialLink[]>([]);
  const [externalLinks, setExternalLinks] = useState<ExternalLink[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);

  useEffect(() => {
    const storedUsers = localStorage.getItem('swl_users');
    if (storedUsers) setUsers(JSON.parse(storedUsers));
    else {
      const admin: User = { id: '1', username: 'admin', email: 'admin@sawahlunto.go.id', password: 'admin', role: 'super_admin', fullName: 'Admin' };
      setUsers([admin]);
      localStorage.setItem('swl_users', JSON.stringify([admin]));
    }
  }, []);

  useEffect(() => {
    const loadNews = async () => {
      if (newsConfig.source === 'google_sheet' && newsConfig.sheetUrl) {
        try {
          const sheetNews = await fetchNewsFromSheet(newsConfig.sheetUrl);
          if (sheetNews.length > 0) setNews(sheetNews);
        } catch (e) { console.error(e); }
      } else setNews(localNews);
    };
    loadNews();
  }, [newsConfig, localNews]);

  const login = (emailOrUsername: string, password: string) => {
    const user = users.find(u => (u.username === emailOrUsername || u.email === emailOrUsername) && u.password === password);
    if (user) { setCurrentUser(user); return true; }
    return false;
  };

  const logout = () => { setCurrentUser(null); setIsAdminOpen(false); };
  const addUser = (newUser: User) => setUsers(prev => [...prev, newUser]);
  const updateUser = (id: string, userData: Partial<User>) => setUsers(prev => prev.map(u => u.id === id ? { ...u, ...userData } : u));
  const deleteUser = (id: string) => setUsers(prev => prev.filter(u => u.id !== id));
  const updateContent = (section: keyof SiteContent, field: string, value: any, lang?: Language) => {
    setContent(prev => {
      const sectionData = prev[section] as any;
      if (lang && typeof sectionData[field] === 'object') return { ...prev, [section]: { ...sectionData, [field]: { ...sectionData[field], [lang]: value } } };
      return { ...prev, [section]: { ...sectionData, [field]: value } };
    });
  };
  const updateTheme = (colors: ThemeColors) => setContent(prev => ({ ...prev, theme: colors }));
  const addHeroSlide = (slide: HeroSlide) => setContent(prev => ({ ...prev, hero: { ...prev.hero, slides: [...prev.hero.slides, slide] } }));
  const updateHeroSlide = (id: string, updatedSlide: HeroSlide) => setContent(prev => ({ ...prev, hero: { ...prev.hero, slides: prev.hero.slides.map(s => s.id === id ? updatedSlide : s) } }));
  const deleteHeroSlide = (id: string) => setContent(prev => ({ ...prev, hero: { ...prev.hero, slides: prev.hero.slides.filter(s => s.id !== id) } }));
  const addArtItem = (item: ArtItem) => setContent(prev => ({ ...prev, arts: { ...prev.arts, items: [...prev.arts.items, item] } }));
  const updateArtItem = (id: string, updatedItem: ArtItem) => setContent(prev => ({ ...prev, arts: { ...prev.arts, items: prev.arts.items.map(a => a.id === id ? updatedItem : a) } }));
  const deleteArtItem = (id: string) => setContent(prev => ({ ...prev, arts: { ...prev.arts, items: prev.arts.items.filter(a => a.id !== id) } }));
  const addTicket = (item: TicketItem) => setContent(prev => ({ ...prev, tickets: { ...prev.tickets, items: [...prev.tickets.items, item] } }));
  const updateTicket = (id: string, updatedItem: TicketItem) => setContent(prev => ({ ...prev, tickets: { ...prev.tickets, items: prev.tickets.items.map(t => t.id === id ? updatedItem : t) } }));
  const deleteTicket = (id: string) => setContent(prev => ({ ...prev, tickets: { ...prev.tickets, items: prev.tickets.items.filter(t => t.id !== id) } }));
  const addNavItem = (item: NavItem) => setNavItems(prev => [...prev, item]);
  const updateNavItem = (id: string, updated: NavItem) => setNavItems(prev => prev.map(i => i.id === id ? updated : i));
  const deleteNavItem = (id: string) => setNavItems(prev => prev.filter(i => i.id !== id));
  const reorderNavItems = (items: NavItem[]) => setNavItems(items);
  const reorderSections = (order: SectionKey[]) => setSectionOrder(order);
  const addAttraction = (attraction: Attraction) => setAttractions(prev => [...prev, attraction]);
  const updateAttraction = (id: string, updated: Attraction) => setAttractions(prev => prev.map(a => a.id === id ? updated : a));
  const deleteAttraction = (id: string) => setAttractions(prev => prev.filter(a => a.id !== id));
  const updateNewsConfig = (config: NewsConfig) => setNewsConfig(config);
  const addNews = (item: NewsItem) => setLocalNews(prev => [...prev, item]);
  const updateNews = (id: string, updated: NewsItem) => setLocalNews(prev => prev.map(n => n.id === id ? updated : n));
  const deleteNews = (id: string) => setLocalNews(prev => prev.filter(n => n.id !== id));
  const addMuseum = (item: MuseumItem) => setMuseums(prev => [...prev, item]);
  const updateMuseum = (id: string, updated: MuseumItem) => setMuseums(prev => prev.map(m => m.id === id ? updated : m));
  const deleteMuseum = (id: string) => setMuseums(prev => prev.filter(m => m.id !== id));
  const addSocialLink = (item: SocialLink) => setSocialLinks(prev => [...prev, item]);
  const updateSocialLink = (id: string, updated: SocialLink) => setSocialLinks(prev => prev.map(s => s.id === id ? updated : s));
  const deleteSocialLink = (id: string) => setSocialLinks(prev => prev.filter(s => s.id !== id));
  const addExternalLink = (item: ExternalLink) => setExternalLinks(prev => [...prev, item]);
  const updateExternalLink = (id: string, updated: ExternalLink) => setExternalLinks(prev => prev.map(l => l.id === id ? updated : l));
  const deleteExternalLink = (id: string) => setExternalLinks(prev => prev.filter(l => l.id !== id));

  return (
    <DataContext.Provider value={{
      language, setLanguage, isAdminOpen, setIsAdminOpen, selectedNewsId, setSelectedNewsId, selectedArtId, setSelectedArtId,
      isAuthenticated: !!currentUser, currentUser, users, login, logout, addUser, updateUser, deleteUser, resetPassword: (e,p) => true,
      content, updateContent, updateTheme, addHeroSlide, updateHeroSlide, deleteHeroSlide, addTicket, updateTicket, deleteTicket,
      addArtItem, updateArtItem, deleteArtItem, navItems, addNavItem, updateNavItem, deleteNavItem, reorderNavItems,
      activeHeritageTab, setActiveHeritageTab, activeInfoTab, setActiveInfoTab, sectionOrder, reorderSections,
      attractions, addAttraction, updateAttraction, deleteAttraction, news, newsConfig, updateNewsConfig, addNews, updateNews, deleteNews,
      museums, addMuseum, updateMuseum, deleteMuseum, socialLinks, addSocialLink, updateSocialLink, deleteSocialLink,
      externalLinks, addExternalLink, updateExternalLink, deleteExternalLink
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) throw new Error('useData must be used within a DataProvider');
  return context;
};

