          <button onClick={() => setIsAdminOpen(false)} className="absolute top-4 right-4 text-gray-400 hover:text-red-500 p-2"><X className="w-5 h-5" /></button>
          <div className="text-center mb-8">
            <h2 className="text-3xl font-serif font-bold text-heritage-dark">{t.adminPortal[language]}</h2>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
              <input type="text" value={loginIdentifier} onChange={(e) => setLoginIdentifier(e.target.value)} className="w-full px-4 py-3 border border-gray-200 rounded-lg" placeholder={t.usernamePlaceholder[language]} required />
              <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="w-full px-4 py-3 border border-gray-200 rounded-lg" placeholder={t.passwordPlaceholder[language]} required />
              <button type="submit" className="w-full bg-heritage-dark text-white font-bold py-3.5 rounded-lg hover:bg-heritage-gold uppercase tracking-widest text-xs">{t.signIn[language]}</button>
          </form>
        </div>
      </div>
    );
  }

  const handleNewsSave = (e: React.FormEvent) => { e.preventDefault(); if(editingNews) { news.find(n=>n.id===editingNews.id) ? updateNews(editingNews.id, editingNews) : addNews(editingNews); setEditingNews(null); }};
  const handleArtItemSave = (e: React.FormEvent) => { e.preventDefault(); if (editingArtItem) { content.arts.items.find(a => a.id === editingArtItem.id) ? updateArtItem(editingArtItem.id, editingArtItem) : addArtItem(editingArtItem); setEditingArtItem(null); } };

  return (
    <div className="fixed inset-0 z-[100] bg-gray-100 flex font-sans overflow-hidden">
      <div className="w-64 bg-heritage-dark text-white flex flex-col shrink-0 h-full border-r border-gray-700">
        <div className="p-6 border-b border-gray-700"><h1 className="font-display font-bold text-xl tracking-wider">CMS PANEL</h1></div>
        <nav className="flex-1 overflow-y-auto py-4">
          {[
            { id: 'general', label: t.general[language], icon: Globe },
            { id: 'theme', label: t.theme[language], icon: Palette },
            { id: 'organization', label: t.organization[language], icon: Users },
            { id: 'sections', label: t.sections[language], icon: FileText },
            { id: 'arts', label: t.arts[language], icon: Music },
            { id: 'news', label: t.news[language], icon: Instagram },
            { id: 'info', label: t.info[language], icon: Phone },
          ].map((item) => (
            <button key={item.id} onClick={() => setActiveSection(item.id as any)} className={`w-full flex items-center gap-3 px-6 py-4 text-sm font-bold uppercase tracking-wider transition-colors ${activeSection === item.id ? 'bg-heritage-gold text-white' : 'text-gray-400 hover:bg-gray-800'}`}>
              <item.icon className="w-4 h-4" /> {item.label}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-gray-700">
          <button onClick={logout} className="w-full py-3 bg-red-600/20 text-red-400 rounded text-sm font-bold uppercase">{t.logout[language]}</button>
          <button onClick={() => setIsAdminOpen(false)} className="w-full mt-2 text-gray-500 text-xs text-center">{t.closePanel[language]}</button>
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full overflow-hidden bg-gray-100 p-8">
        <h2 className="text-2xl font-serif font-bold text-heritage-dark capitalize mb-8">{activeSection.replace('_', ' ')}</h2>
        <div className="max-w-4xl space-y-8 overflow-y-auto pr-4 custom-scrollbar">
            {activeSection === 'news' && (
                <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="font-bold text-lg text-heritage-dark border-l-4 border-heritage-gold pl-3">{t.news[language]}</h3>
                        <button onClick={() => setEditingNews({ id: Date.now().toString(), title: { en: '', id: '' }, date: new Date().toISOString().split('T')[0], summary: { en: '', id: '' }, content: { en: '', id: '' }, imageUrl: 'https://picsum.photos/800/600', imageUrls: [] })} className="btn-add"><Plus className="w-4 h-4" /> {t.newPost[language]}</button>
                    </div>
                    {editingNews ? (
                        <form onSubmit={handleNewsSave} className="bg-gray-50 p-6 rounded border space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="input-label">Judul (ID)</label><input required type="text" value={editingNews.title.id} onChange={e => setEditingNews({...editingNews, title: {...editingNews.title, id: e.target.value}})} className="input-field" /></div>
                                <div><label className="input-label">Tanggal</label><input required type="date" value={editingNews.date} onChange={e => setEditingNews({...editingNews, date: e.target.value})} className="input-field" /></div>
                            </div>
                            <div><label className="input-label">Ringkasan (ID)</label><textarea required value={editingNews.summary.id} onChange={e => setEditingNews({...editingNews, summary: {...editingNews.summary, id: e.target.value}})} className="input-field h-20" /></div>
                            <div><label className="input-label">Konten Lengkap (ID)</label><textarea required value={editingNews.content.id} onChange={e => setEditingNews({...editingNews, content: {...editingNews.content, id: e.target.value}})} className="input-field h-40" /></div>
                            <div className="p-4 bg-white rounded border border-gray-200 space-y-4">
                                <label className="input-label mb-0">Galeri Foto (URLs)</label>
                                <div><label className="input-label text-[9px]">Foto Utama</label><input required type="text" value={editingNews.imageUrl} onChange={e => setEditingNews({...editingNews, imageUrl: e.target.value})} className="input-field" /></div>
                                {(editingNews.imageUrls || []).map((url, idx) => (
                                    <div key={idx} className="flex gap-2">
                                        <input type="text" value={url} onChange={e => { const newUrls = [...(editingNews.imageUrls || [])]; newUrls[idx] = e.target.value; setEditingNews({...editingNews, imageUrls: newUrls}); }} className="input-field" placeholder={`Foto Tambahan ${idx+1}`} />
                                        <button type="button" onClick={() => setEditingNews({...editingNews, imageUrls: (editingNews.imageUrls || []).filter((_, i) => i !== idx)})} className="text-red-500"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                ))}
                                <button type="button" onClick={() => setEditingNews({...editingNews, imageUrls: [...(editingNews.imageUrls || []), '']})} className="text-xs font-bold text-heritage-gold flex items-center gap-1"><PlusCircle className="w-3 h-3"/> Tambah Foto</button>
