                                <label className="input-label mb-0">Galeri Kesenian</label>
                                <div><label className="input-label text-[9px]">Foto Utama</label><input required type="text" value={editingArtItem.imageUrl} onChange={e => setEditingArtItem({...editingArtItem, imageUrl: e.target.value})} className="input-field" /></div>
                                {(editingArtItem.imageUrls || []).map((url, idx) => (
                                    <div key={idx} className="flex gap-2">
                                        <input type="text" value={url} onChange={e => { const newUrls = [...(editingArtItem.imageUrls || [])]; newUrls[idx] = e.target.value; setEditingArtItem({...editingArtItem, imageUrls: newUrls}); }} className="input-field" />
                                        <button type="button" onClick={() => setEditingArtItem({...editingArtItem, imageUrls: (editingArtItem.imageUrls || []).filter((_, i) => i !== idx)})} className="text-red-500"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                ))}
                                <button type="button" onClick={() => setEditingArtItem({...editingArtItem, imageUrls: [...(editingArtItem.imageUrls || []), '']})} className="text-xs font-bold text-heritage-gold flex items-center gap-1"><PlusCircle className="w-3 h-3"/> Tambah Foto</button>
                            </div>
                            <div className="flex gap-2"><button type="submit" className="btn-primary flex-1">Simpan</button><button type="button" onClick={() => setEditingArtItem(null)} className="btn-secondary">Batal</button></div>
                        </form>
                    ) : (
                        <div className="space-y-4">
                            {content.arts.items.map(item => (
                                <div key={item.id} className="flex gap-4 p-4 bg-gray-50 rounded border items-center">
                                    <img src={item.imageUrl} className="w-16 h-16 object-cover rounded shadow-sm" alt="" />
                                    <div className="flex-1 font-bold text-heritage-dark">{item.title.id}</div>
                                    <div className="flex gap-2"><button onClick={() => setEditingArtItem(item)} className="text-blue-500"><Edit2 className="w-4 h-4" /></button><button onClick={() => deleteArtItem(item.id)} className="text-red-500"><Trash2 className="w-4 h-4" /></button></div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}
        </div>
      </div>
      <style>{`
        .input-label { display: block; font-size: 0.75rem; font-weight: 700; color: #6b7280; text-transform: uppercase; margin-bottom: 0.25rem; }
        .input-field { width: 100%; border: 1px solid #d1d5db; padding: 0.5rem; border-radius: 0.375rem; font-size: 0.875rem; }
        .btn-add { display: flex; align-items: center; gap: 0.5rem; color: #C5A059; border: 1px dashed #C5A059; padding: 0.5rem 1rem; border-radius: 0.375rem; font-weight: 700; font-size: 0.75rem; }
        .btn-primary { background-color: #1C1C1C; color: white; font-weight: 700; padding: 0.75rem; border-radius: 0.375rem; }
        .btn-secondary { color: #6b7280; font-weight: 600; padding: 0.75rem 1.5rem; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #E5E7EB; border-radius: 10px; }
      `}</style>
    </div>
  );
};

