interface DataContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  isAdminOpen: boolean;
  setIsAdminOpen: (isOpen: boolean) => void;

  // News Detail State
  selectedNewsId: string | null;
  setSelectedNewsId: (id: string | null) => void;

  // Art Detail State
  selectedArtId: string | null;
  setSelectedArtId: (id: string | null) => void;

  // Auth
  isAuthenticated: boolean;
  currentUser: User | null;
  users: User[];
  login: (emailOrUsername: string, password: string) => boolean;
  logout: () => void;
  addUser: (user: User) => void;
  updateUser: (id: string, userData: Partial<User>) => void;
  deleteUser: (id: string) => void;
  resetPassword: (email: string, newPass: string) => boolean;

  content: SiteContent;
  updateContent: (section: keyof SiteContent, field: string, value: any, lang?: Language) => void;
