const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguage] = useState<Language>('id');
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [selectedNewsId, setSelectedNewsId] = useState<string | null>(null);
  const [selectedArtId, setSelectedArtId] = useState<string | null>(null);
  const [content, setContent] = useState<SiteContent>(defaultContent);
  const [navItems, setNavItems] = useState<NavItem[]>(defaultNavItems);
  const [activeHeritageTab, setActiveHeritageTab] = useState<'tangible' | 'intangible'>('tangible');
  const [activeInfoTab, setActiveInfoTab] = useState<'tickets' | 'vision' | 'org' | 'map'>('tickets');
  const [sectionOrder, setSectionOrder] = useState<SectionKey[]>(['hero', 'map', 'portals', 'heritage', 'arts', 'news', 'attractions', 'info']);
  const [attractions, setAttractions] = useState<Attraction[]>([]);
  const [localNews, setLocalNews] = useState<NewsItem[]>([]);
  const [news, setNews] = useState<NewsItem[]>([]);
  const [newsConfig, setNewsConfig] = useState<NewsConfig>({ source: 'local', sheetUrl: '' });
  const [museums, setMuseums] = useState<MuseumItem[]>([]);
  const [socialLinks, setSocialLinks] = useState<SocialLink[]>([]);
  const [externalLinks, setExternalLinks] = useState<ExternalLink[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);

  useEffect(() => {
    const storedUsers = localStorage.getItem('swl_users');
    if (storedUsers) setUsers(JSON.parse(storedUsers));
    else {
      const admin: User = { id: '1', username: 'admin', email: 'admin@sawahlunto.go.id', password: 'admin', role: 'super_admin', fullName: 'Admin' };
      setUsers([admin]);
      localStorage.setItem('swl_users', JSON.stringify([admin]));
    }
  }, []);

  useEffect(() => {
    const loadNews = async () => {
      if (newsConfig.source === 'google_sheet' && newsConfig.sheetUrl) {
        try {
          const sheetNews = await fetchNewsFromSheet(newsConfig.sheetUrl);
          if (sheetNews.length > 0) setNews(sheetNews);
        } catch (e) { console.error(e); }
      } else setNews(localNews);
    };
    loadNews();
  }, [newsConfig, localNews]);

  const login = (emailOrUsername: string, password: string) => {
    const user = users.find(u => (u.username === emailOrUsername || u.email === emailOrUsername) && u.password === password);
    if (user) { setCurrentUser(user); return true; }
    return false;
  };

  const logout = () => { setCurrentUser(null); setIsAdminOpen(false); };
  const addUser = (newUser: User) => setUsers(prev => [...prev, newUser]);
  const updateUser = (id: string, userData: Partial<User>) => setUsers(prev => prev.map(u => u.id === id ? { ...u, ...userData } : u));
  const deleteUser = (id: string) => setUsers(prev => prev.filter(u => u.id !== id));

  const resetPassword = (email: string, newPass: string) => {
    const user = users.find(u => u.email === email);
    if (user) {
      updateUser(user.id, { password: newPass });
      return true;
    }
    return false;
  };

  const updateContent = (section: keyof SiteContent, field: string, value: any, lang?: Language) => {
    setContent(prev => {
      const sectionData = prev[section] as any;
