              </div>
              <div className="relative group">
                  <Key className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-heritage-gold" />
                  <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:border-heritage-gold focus:ring-1 focus:ring-heritage-gold text-sm" placeholder={t.passwordPlaceholder[language]} required />
