                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}
            {activeSection === 'arts' && (
                <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="font-bold text-lg text-heritage-dark border-l-4 border-heritage-gold pl-3">{t.arts[language]}</h3>
