                            <div><label className="input-label">Deskripsi Singkat (ID)</label><textarea required value={editingArtItem.description.id} onChange={e => setEditingArtItem({...editingArtItem, description: {...editingArtItem.description, id: e.target.value}})} className="input-field h-24" /></div>
                            <div><label className="input-label">Narasi Lengkap (ID)</label><textarea required value={editingArtItem.content?.id || ''} onChange={e => setEditingArtItem({...editingArtItem, content: { en: '', id: e.target.value}})} className="input-field h-40" /></div>
