import React, { useEffect, useState } from 'react';
import { useData } from '../contexts/DataContext';
import { X, Music, Maximize2, Share2 } from 'lucide-react';

const ArtDetail: React.FC = () => {
  const { content, selectedArtId, setSelectedArtId, language } = useData();
  const [activePhoto, setActivePhoto] = useState<string | null>(null);

  const selectedArt = content.arts.items.find(item => item.id === selectedArtId);
  const images = [selectedArt?.imageUrl, ...(selectedArt?.imageUrls || [])].filter(img => typeof img === 'string' && img.trim() !== '');

  useEffect(() => {
    if (selectedArtId) document.body.style.overflow = 'hidden';
    else document.body.style.overflow = 'unset';
    return () => { document.body.style.overflow = 'unset'; };
  }, [selectedArtId]);

  if (!selectedArtId || !selectedArt) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-8 animate-fade-in" onClick={() => setSelectedArtId(null)}>
      <div className="absolute inset-0 bg-black/80 backdrop-blur-sm"></div>
      <div className="relative bg-white w-full max-w-7xl h-full max-h-[90vh] md:h-[85vh] rounded-[2.5rem] shadow-2xl overflow-hidden flex flex-col md:flex-row animate-scale-in" onClick={(e) => e.stopPropagation()}>
        <button onClick={() => setSelectedArtId(null)} className="absolute top-4 right-4 z-30 md:hidden bg-black/50 text-white p-2 rounded-full backdrop-blur-md">
          <X className="w-5 h-5" />
        </button>

        <div className="w-full md:w-[55%] h-80 md:h-full bg-gray-50 relative overflow-hidden">
          <div className={`p-4 md:p-8 grid gap-4 h-full ${images.length === 1 ? 'grid-cols-1' : 'grid-cols-2 grid-rows-2'}`}>
            {images.slice(0, 4).map((img, idx) => (
              <div key={idx} className={`relative rounded-2xl overflow-hidden shadow-lg border-4 border-white cursor-pointer group/img transition-all duration-500 h-full ${images.length === 3 && idx === 0 ? 'row-span-2' : ''}`} onClick={() => setActivePhoto(img)}>
                <img src={img} className="w-full h-full object-cover transition-transform duration-700 group-hover/img:scale-110" alt="" />
                <div className="absolute inset-0 bg-black/0 group-hover/img:bg-black/20 transition-all flex items-center justify-center">
                    <Maximize2 className="w-8 h-8 text-white opacity-0 group-hover/img:opacity-100 transform scale-50 group-hover/img:scale-100 transition-all" />
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="flex-1 flex flex-col h-full bg-white relative border-l border-gray-100">
          <div className="p-8 pb-4">
            <div className="flex justify-between items-start mb-4 text-heritage-gold">
                <div className="flex items-center gap-2"><Music className="w-4 h-4" /><span className="text-[10px] font-black uppercase tracking-[0.2em]">Seni & Budaya</span></div>
                <button onClick={() => setSelectedArtId(null)} className="hidden md:block text-gray-300 hover:text-heritage-dark transition-colors"><X className="w-6 h-6" /></button>
            </div>
            <h2 className="font-serif text-3xl md:text-4xl font-bold text-heritage-dark leading-[1.1]">{selectedArt.title[language]}</h2>
          </div>
          <div className="flex-1 overflow-y-auto px-8 py-4 custom-scrollbar">
            <p className="font-bold text-heritage-dark text-xl mb-8 italic border-l-4 border-heritage-gold pl-6 py-2 bg-gray-50 rounded-r-xl">{selectedArt.description[language]}</p>
            <div className="whitespace-pre-line text-lg text-gray-600 leading-[1.8]">{selectedArt.content ? selectedArt.content[language] : 'Narasi lengkap sedang disiapkan.'}</div>
          </div>
          <div className="p-8 bg-gray-50 border-t border-gray-100">
            <button className="flex items-center gap-2 bg-heritage-dark text-white px-6 py-3 rounded-xl font-bold uppercase tracking-widest text-xs hover:bg-heritage-gold transition-all"><Share2 className="w-4 h-4" /><span>Bagikan</span></button>
          </div>
        </div>
      </div>
      {activePhoto && <div className="fixed inset-0 z-[110] bg-black/95 flex items-center justify-center p-4 animate-fade-in" onClick={() => setActivePhoto(null)}><img src={activePhoto} className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-scale-in" alt="" /></div>}
    </div>
  );
};

export default ArtDetail;

