import React, { useEffect, useState } from 'react';
import { useData } from '../contexts/DataContext';
import { X, ArrowLeft, Calendar, Share2, Facebook, Twitter, Link as LinkIcon, Clock, CheckCircle } from 'lucide-react';

const NewsDetail: React.FC = () => {
  const { news, selectedNewsId, setSelectedNewsId, language } = useData();
  const [isScrolled, setIsScrolled] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const selectedNews = news.find(item => item.id === selectedNewsId);

  useEffect(() => {
    if (selectedNewsId) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [selectedNewsId]);

  if (!selectedNewsId || !selectedNews) return null;

  const shareUrl = `${window.location.origin}${window.location.pathname}#news-${selectedNews.id}`;
  const shareTitle = selectedNews.title[language];

  const handleNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: shareTitle,
          text: selectedNews.summary[language],
          url: shareUrl,
        });
      } catch (err) {
        if ((err as Error).name !== 'AbortError') {
          console.error('Error sharing:', err);
        }
      }
    } else {
      copyToClipboard();
    }
  };

  const shareOnFacebook = () => {
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`, '_blank', 'width=600,height=400');
  };

  const shareOnTwitter = () => {
    const text = `${shareTitle}\n\n`;
    window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(shareUrl)}`, '_blank', 'width=600,height=400');
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(shareUrl).then(() => {
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    });
  };

  return (
    <div className="fixed inset-0 z-[100] bg-white overflow-y-auto animate-fade-in custom-scrollbar">
      {/* Dynamic Header */}
      <div className={`fixed top-0 left-0 w-full z-20 transition-all duration-300 px-6 py-4 flex justify-between items-center ${
        isScrolled ? 'bg-white shadow-md border-b border-gray-100' : 'bg-transparent'
      }`}>
        <button 
          onClick={() => setSelectedNewsId(null)}
          className={`flex items-center gap-2 px-4 py-2 rounded-full font-bold uppercase tracking-widest text-[10px] transition-all ${
            isScrolled ? 'bg-heritage-dark text-white' : 'bg-white/90 backdrop-blur text-heritage-dark shadow-xl'
          }`}
        >
          <ArrowLeft className="w-4 h-4" />
          {language === 'en' ? 'Back' : 'Kembali'}
        </button>

        <div className="flex gap-2">
            <button 
              onClick={handleNativeShare}
              className={`p-2 rounded-full transition-all relative ${isScrolled ? 'bg-gray-100 text-heritage-dark' : 'bg-white/90 backdrop-blur text-heritage-dark shadow-xl'}`}
              title={language === 'en' ? 'Share Article' : 'Bagikan Berita'}
            >
                <Share2 className="w-4 h-4" />
                {copySuccess && (
                  <span className="absolute -bottom-8 right-0 bg-heritage-dark text-white text-[8px] py-1 px-2 rounded whitespace-nowrap animate-fade-in">
                    {language === 'en' ? 'Link Copied!' : 'Tautan Tersalin!'}
                  </span>
                )}
            </button>
            <button 
                onClick={() => setSelectedNewsId(null)}
                className={`p-2 rounded-full transition-all ${isScrolled ? 'bg-heritage-dark text-white' : 'bg-white/90 backdrop-blur text-heritage-dark shadow-xl'}`}
            >
                <X className="w-4 h-4" />
            </button>
        </div>
      </div>

      <div onScroll={(e) => setIsScrolled(e.currentTarget.scrollTop > 100)} className="h-full">
        {/* Article Hero */}
        <div className="relative h-[50vh] md:h-[65vh] w-full">
          <img 
            src={selectedNews.imageUrl} 
            alt={selectedNews.title[language]} 
            className="w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-white via-transparent to-black/30"></div>

          <div className="absolute bottom-0 left-0 w-full p-8 md:p-16">
            <div className="container mx-auto max-w-4xl">
                <div className="flex items-center gap-3 mb-4">
                    <div className="bg-heritage-gold text-white px-3 py-1 rounded text-[10px] font-bold uppercase tracking-widest">
                        Sawahlunto Update
                    </div>
                </div>
                <h1 className="font-serif text-4xl md:text-6xl font-bold text-heritage-dark md:text-white leading-[1.1]">
                    {selectedNews.title[language]}
                </h1>
            </div>
          </div>
        </div>

        {/* Content Section */}
        <div className="container mx-auto max-w-4xl px-6 pb-24 -mt-10 md:-mt-16 relative z-10">
          <div className="bg-white rounded-3xl p-8 md:p-16 shadow-2xl border border-gray-100">

            {/* Meta Info */}
            <div className="flex flex-wrap items-center gap-6 mb-12 pb-8 border-b border-gray-100 text-gray-400 font-bold uppercase tracking-widest text-[10px]">
                <div className="flex items-center gap-2">
                    <Calendar className="w-4 h-4 text-heritage-gold" />
                    {new Date(selectedNews.date).toLocaleDateString(language === 'en' ? 'en-US' : 'id-ID', { 
                        year: 'numeric', month: 'long', day: 'numeric' 
                    })}
                </div>
                <div className="flex items-center gap-2">
                    <Clock className="w-4 h-4 text-heritage-gold" />
                    {language === 'en' ? '5 min read' : 'Baca 5 menit'}
                </div>
            </div>

            {/* Lead Summary */}
            <p className="text-xl md:text-2xl font-serif text-heritage-dark italic leading-relaxed mb-10 text-center md:text-left">
              {selectedNews.summary[language]}
            </p>

            {/* Article Content */}
            <div className="prose prose-lg max-w-none text-gray-700 font-sans leading-[1.8] whitespace-pre-line text-lg">
               {selectedNews.content[language]}
            </div>

            {/* Share & Footer */}
            <div className="mt-20 pt-10 border-t border-gray-100">
                <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-heritage-dark text-white rounded-full flex items-center justify-center font-bold">SWL</div>
                        <div>
                            <span className="block text-[10px] font-black uppercase tracking-widest text-heritage-dark">Publikasi Resmi</span>
                            <span className="text-xs text-gray-400">Dinas Kebudayaan Kota Sawahlunto</span>
                        </div>
                    </div>

                    <div className="flex gap-3 relative">
                        <button 
                          onClick={shareOnFacebook}
                          className="w-10 h-10 rounded-full border border-gray-200 flex items-center justify-center hover:bg-[#1877F2] hover:text-white hover:border-[#1877F2] transition-all text-gray-400"
                          title="Share on Facebook"
                        >
                            <Facebook className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={shareOnTwitter}
                          className="w-10 h-10 rounded-full border border-gray-200 flex items-center justify-center hover:bg-black hover:text-white hover:border-black transition-all text-gray-400"
                          title="Share on X (Twitter)"
                        >
                            <Twitter className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={copyToClipboard}
                          className={`w-10 h-10 rounded-full border flex items-center justify-center transition-all ${
                            copySuccess ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200 text-gray-400 hover:bg-heritage-gold hover:text-white hover:border-heritage-gold'
                          }`}
                          title={language === 'en' ? 'Copy Link' : 'Salin Tautan'}
                        >
                            {copySuccess ? <CheckCircle className="w-4 h-4" /> : <LinkIcon className="w-4 h-4" />}
                        </button>
                    </div>
                </div>
            </div>
          </div>

          <div className="mt-12 text-center">
             <button 
                onClick={() => setSelectedNewsId(null)}
                className="text-heritage-gold font-black uppercase tracking-[0.3em] text-[10px] hover:tracking-[0.4em] transition-all"
             >
                {language === 'en' ? 'Return to archives' : 'Kembali ke daftar berita'}
             </button>
          </div>
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 8px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f8f8f8;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #C5A059;
          border-radius: 4px;
        }
      `}</style>
    </div>
  );
};

