  X, Plus, Trash2, Edit2, Globe, Palette, Users, FileText, Music, Instagram, 
  Phone, Ticket, MapPin, Navigation, Layout, User as UserIcon, Key, 
  AlertTriangle, Save, PlusCircle, ArrowUp, ArrowDown, Link as LinkIcon, 
  Image as ImageIcon, CheckCircle, Info, Landmark, Calendar, Clock, Camera
} from 'lucide-react';
import { 
  Attraction, NewsItem, MuseumItem, SocialLink, ExternalLink, 
  NavItem, SectionKey, User, TicketItem, HeroSlide, ArtItem, ThemeColors 
} from '../types';

const t = {
  adminPortal: { en: 'Admin Portal', id: 'Portal Admin' },
  cmsName: { en: 'Sawahlunto Heritage CMS', id: 'CMS Warisan Sawahlunto' },
  usernamePlaceholder: { en: 'Username or Email', id: 'Username atau Email' },
  passwordPlaceholder: { en: 'Password', id: 'Kata Sandi' },
  signIn: { en: 'Sign In', id: 'Masuk' },
  errorMsg: { en: 'Invalid username or password.', id: 'Username atau password salah.' },
  general: { en: 'Branding & Socials', id: 'Branding & Sosmed' },
  theme: { en: 'Theme & Colors', id: 'Tema & Warna' },
  organization: { en: 'Organization', id: 'Organisasi' },
  navigation: { en: 'Navigation Menu', id: 'Menu Navigasi' },
  sections: { en: 'Heritage Content', id: 'Konten Warisan' },
  arts: { en: 'Arts & Culture', id: 'Seni & Budaya' },
  news: { en: 'News & Media', id: 'Berita & Media' },
  destinations: { en: 'Attractions', id: 'Objek Wisata' },
  info: { en: 'Contact Info', id: 'Info Kontak' },
  tickets: { en: 'Tickets & Hours', id: 'Tiket & Jam' },
  logout: { en: 'Logout', id: 'Keluar' },
  closePanel: { en: 'Close Panel', id: 'Tutup Panel' },
  save: { en: 'Save Changes', id: 'Simpan Perubahan' }
};

const AdminPanel: React.FC = () => {
  const { 
    language, isAdminOpen, setIsAdminOpen, isAuthenticated, login, logout,
    content, updateContent, updateTheme, news, addNews, updateNews, deleteNews,
    navItems, addNavItem, updateNavItem, deleteNavItem,
    socialLinks, addSocialLink, deleteSocialLink,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addArtItem, updateArtItem, deleteArtItem
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isShaking, setIsShaking] = useState(false);
  const [activeSection, setActiveSection] = useState<string>('general');

  // Modal / Editing States
  const [editingNews, setEditingNews] = useState<NewsItem | null>(null);
  const [editingArt, setEditingArt] = useState<ArtItem | null>(null);
  const [editingAttraction, setEditingAttraction] = useState<Attraction | null>(null);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError(false);
    if(!login(loginIdentifier, loginPassword)) {
      setLoginError(true);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  };

  const handleAddNewsImage = () => {
    if (!editingNews) return;
    const currentImages = editingNews.imageUrls || [];
    setEditingNews({
      ...editingNews,
      imageUrls: [...currentImages, '']
    });
  };

  const handleUpdateNewsImage = (index: number, val: string) => {
    if (!editingNews || !editingNews.imageUrls) return;
    const newImages = [...editingNews.imageUrls];
    newImages[index] = val;
    setEditingNews({ ...editingNews, imageUrls: newImages });
  };

  const handleRemoveNewsImage = (index: number) => {
    if (!editingNews || !editingNews.imageUrls) return;
    const newImages = editingNews.imageUrls.filter((_, i) => i !== index);
    setEditingNews({ ...editingNews, imageUrls: newImages });
  };

  if (!isAdminOpen) return null;

  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-heritage-dark/95 backdrop-blur-md p-4 animate-fade-in">
        <div className={`bg-white rounded-3xl w-full max-w-md shadow-2xl relative p-10 transition-transform ${isShaking ? 'animate-shake' : ''}`}>
          <button onClick={() => setIsAdminOpen(false)} className="absolute top-6 right-6 text-gray-300 hover:text-red-500 p-2 transition-colors"><X className="w-6 h-6" /></button>
          <div className="text-center mb-10">
            <div className="w-16 h-16 bg-heritage-gold/10 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <Landmark className="w-8 h-8 text-heritage-gold" />
            </div>
            <h2 className="text-3xl font-serif font-bold text-heritage-dark">{t.adminPortal[language]}</h2>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mt-2">{t.cmsName[language]}</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            {loginError && (
              <div className="bg-red-50 border border-red-100 p-4 rounded-xl flex items-center gap-3 animate-fade-in">
                <AlertTriangle className="w-5 h-5 text-red-500 shrink-0" />
                <p className="text-red-700 text-xs font-bold">{t.errorMsg[language]}</p>
              </div>
            )}
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Identity</label>
              <div className="relative group">
                <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-heritage-gold transition-colors" />
                <input type="text" value={loginIdentifier} onChange={(e) => setLoginIdentifier(e.target.value)} className="w-full pl-12 pr-4 py-4 bg-white border border-gray-200 rounded-xl focus:outline-none focus:border-heritage-gold transition-all text-sm" placeholder={t.usernamePlaceholder[language]} required />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Security</label>
              <div className="relative group">
                <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-heritage-gold transition-colors" />
                <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="w-full pl-12 pr-4 py-4 bg-white border border-gray-200 rounded-xl focus:outline-none focus:border-heritage-gold transition-all text-sm" placeholder={t.passwordPlaceholder[language]} required />
              </div>
            </div>
            <button type="submit" className="w-full bg-heritage-dark text-white font-bold py-4 rounded-xl hover:bg-heritage-gold transition-all shadow-xl uppercase tracking-[0.2em] text-xs mt-4">
              {t.signIn[language]}
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[100] bg-gray-100 flex font-sans overflow-hidden">
      {/* Sidebar Navigation */}
      <div className="w-72 bg-heritage-dark text-white flex flex-col shrink-0 h-full border-r border-gray-800">
        <div className="p-8 border-b border-gray-800">
          <div className="flex items-center gap-3">
             <div className="w-8 h-8 bg-heritage-gold rounded-lg flex items-center justify-center font-black text-white">S</div>
             <h1 className="font-display font-bold text-lg tracking-wider">DASHBOARD</h1>
          </div>
        </div>
        <nav className="flex-1 overflow-y-auto py-6 scrollbar-hide">
          {[
            { id: 'general', label: t.general[language], icon: Globe },
            { id: 'theme', label: t.theme[language], icon: Palette },
            { id: 'navigation', label: t.navigation[language], icon: Navigation },
            { id: 'organization', label: t.organization[language], icon: Users },
            { id: 'sections', label: t.sections[language], icon: FileText },
            { id: 'arts', label: t.arts[language], icon: Music },
            { id: 'news', label: t.news[language], icon: Instagram },
            { id: 'destinations', label: t.destinations[language], icon: MapPin },
            { id: 'tickets', label: t.tickets[language], icon: Ticket },
            { id: 'info', label: t.info[language], icon: Phone },
          ].map((item) => (
            <button 
              key={item.id} 
              onClick={() => setActiveSection(item.id)} 
              className={`w-full flex items-center gap-4 px-8 py-4 text-[10px] font-bold uppercase tracking-[0.2em] transition-all relative ${
                activeSection === item.id 
                ? 'text-white bg-white/5' 
                : 'text-gray-500 hover:text-gray-300 hover:bg-white/5'
              }`}
            >
              {activeSection === item.id && <div className="absolute left-0 top-0 w-1 h-full bg-heritage-gold" />}
              <item.icon className={`w-4 h-4 ${activeSection === item.id ? 'text-heritage-gold' : ''}`} /> 
              {item.label}
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-gray-800 space-y-3">
          <button onClick={logout} className="w-full py-3.5 bg-red-600/10 text-red-500 border border-red-600/20 rounded-xl text-[10px] font-bold uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all">
            {t.logout[language]}
          </button>
          <button onClick={() => setIsAdminOpen(false)} className="w-full text-gray-500 text-[10px] text-center uppercase font-bold tracking-widest hover:text-white transition-colors">
            {t.closePanel[language]}
          </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 flex flex-col h-full overflow-hidden bg-gray-50">
        <header className="bg-white border-b border-gray-200 px-12 py-6 flex justify-between items-center shrink-0">
          <h2 className="text-2xl font-serif font-bold text-heritage-dark capitalize">
            {activeSection.replace('_', ' ')}
          </h2>
          <div className="flex items-center gap-4">
             <div className="text-right">
                <span className="block text-[10px] font-black text-heritage-dark uppercase tracking-widest">Admin Session</span>
                <span className="text-xs text-gray-400">Sawahlunto Cultural Heritage</span>
             </div>
             <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center text-heritage-dark font-bold border border-gray-200">
                A
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto custom-scrollbar">
          <div className="max-w-5xl mx-auto p-12 space-y-10">

            {/* SECTION: GENERAL (BRANDING) */}
            {activeSection === 'general' && (
              <div className="space-y-8 animate-fade-in">
                <div className="bg-white p-10 rounded-3xl shadow-sm border border-gray-200">
                  <div className="flex items-center gap-3 mb-8">
                    <div className="p-2 bg-heritage-gold/10 rounded-lg"><Landmark className="w-5 h-5 text-heritage-gold" /></div>
                    <h3 className="font-bold text-xs text-gray-400 uppercase tracking-[0.2em]">Identity Branding</h3>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-2">
                      <label className="input-label">Site Name</label>
                      <input type="text" value={content.branding.siteName} onChange={(e) => updateContent('branding', 'siteName', e.target.value)} className="input-field" placeholder="E.g. SAWAHLUNTO" />
                    </div>
                    <div className="space-y-2">
                      <label className="input-label">Subtitle / Motto</label>
                      <input type="text" value={content.branding.subTitle} onChange={(e) => updateContent('branding', 'subTitle', e.target.value)} className="input-field" placeholder="E.g. UNESCO World Heritage" />
                    </div>
                    <div className="space-y-2 md:col-span-2">
                      <label className="input-label">Logo Image URL</label>
                      <input type="text" value={content.branding.logoUrl} onChange={(e) => updateContent('branding', 'logoUrl', e.target.value)} className="input-field" placeholder="https://..." />
                    </div>
                  </div>
                </div>

                <div className="bg-white p-10 rounded-3xl shadow-sm border border-gray-200">
                  <div className="flex justify-between items-center mb-8">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-heritage-gold/10 rounded-lg"><LinkIcon className="w-5 h-5 text-heritage-gold" /></div>
                      <h3 className="font-bold text-xs text-gray-400 uppercase tracking-[0.2em]">Social Media Links</h3>
                    </div>
                    <button onClick={() => addSocialLink({ id: Date.now().toString(), platform: 'Instagram', url: '#' })} className="text-heritage-gold text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-heritage-gold hover:text-white px-4 py-2 rounded-lg border border-heritage-gold/30 transition-all">
                      <PlusCircle className="w-4 h-4" /> Add Social Link
                    </button>
                  </div>
                  <div className="space-y-4">
                    {socialLinks.map((link) => (
                      <div key={link.id} className="flex gap-4 items-center animate-slide-up bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <div className="w-32">
                           <label className="input-label">Platform</label>
                           <select className="input-field py-2 text-xs" value={link.platform} disabled>
                              <option>{link.platform}</option>
                           </select>
                        </div>
                        <div className="flex-1">
                           <label className="input-label">URL Profile</label>
                           <input type="text" value={link.url} className="input-field py-2" readOnly />
                        </div>
                        <button onClick={() => deleteSocialLink(link.id)} className="p-3 text-red-400 hover:bg-red-50 rounded-xl transition-all self-end mb-1"><Trash2 className="w-5 h-5" /></button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* SECTION: THEME */}
            {activeSection === 'theme' && (
              <div className="bg-white p-10 rounded-3xl shadow-sm border border-gray-200 animate-fade-in">
                <div className="flex items-center gap-3 mb-10">
                  <div className="p-2 bg-heritage-gold/10 rounded-lg"><Palette className="w-5 h-5 text-heritage-gold" /></div>
                  <h3 className="font-bold text-xs text-gray-400 uppercase tracking-[0.2em]">Color Palette System</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                  <div className="p-6 bg-gray-50 rounded-2xl border border-gray-100 flex items-center gap-6">
                    <input type="color" value={content.theme.primary} onChange={(e) => updateTheme({...content.theme, primary: e.target.value})} className="h-16 w-16 cursor-pointer rounded-lg border-2 border-white shadow-md bg-transparent" />
                    <div className="flex-1">
                      <label className="input-label">Primary Color (Gold)</label>
                      <input type="text" value={content.theme.primary} onChange={(e) => updateTheme({...content.theme, primary: e.target.value})} className="input-field font-mono" />
                    </div>
                  </div>
                  <div className="p-6 bg-gray-50 rounded-2xl border border-gray-100 flex items-center gap-6">
                    <input type="color" value={content.theme.secondary} onChange={(e) => updateTheme({...content.theme, secondary: e.target.value})} className="h-16 w-16 cursor-pointer rounded-lg border-2 border-white shadow-md bg-transparent" />
                    <div className="flex-1">
                      <label className="input-label">Secondary Color (Brick)</label>
                      <input type="text" value={content.theme.secondary} onChange={(e) => updateTheme({...content.theme, secondary: e.target.value})} className="input-field font-mono" />
                    </div>
                  </div>
                  <div className="p-6 bg-gray-50 rounded-2xl border border-gray-100 flex items-center gap-6">
                    <input type="color" value={content.theme.background} onChange={(e) => updateTheme({...content.theme, background: e.target.value})} className="h-16 w-16 cursor-pointer rounded-lg border-2 border-white shadow-md bg-transparent" />
                    <div className="flex-1">
                      <label className="input-label">Background Color</label>
                      <input type="text" value={content.theme.background} onChange={(e) => updateTheme({...content.theme, background: e.target.value})} className="input-field font-mono" />
                    </div>
                  </div>
                  <div className="p-6 bg-gray-50 rounded-2xl border border-gray-100 flex items-center gap-6">
                    <input type="color" value={content.theme.dark} onChange={(e) => updateTheme({...content.theme, dark: e.target.value})} className="h-16 w-16 cursor-pointer rounded-lg border-2 border-white shadow-md bg-transparent" />
                    <div className="flex-1">
                      <label className="input-label">Dark Element Color</label>
                      <input type="text" value={content.theme.dark} onChange={(e) => updateTheme({...content.theme, dark: e.target.value})} className="input-field font-mono" />
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* SECTION: NAVIGATION */}
            {activeSection === 'navigation' && (
              <div className="bg-white p-10 rounded-3xl shadow-sm border border-gray-200 animate-fade-in">
                <div className="flex justify-between items-center mb-10">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-heritage-gold/10 rounded-lg"><Navigation className="w-5 h-5 text-heritage-gold" /></div>
                    <h3 className="font-bold text-xs text-gray-400 uppercase tracking-[0.2em]">Public Menu Management</h3>
                  </div>
                  <button onClick={() => addNavItem({ id: Date.now().toString(), label: {en:'',id:'Menu Baru'}, href: '#' })} className="btn-add">
                    <Plus className="w-4 h-4" /> Add Nav Item
                  </button>
                </div>
                <div className="space-y-4">
                  {navItems.map((item) => (
                    <div key={item.id} className="p-6 bg-gray-50 rounded-2xl border border-gray-200 flex items-center gap-6 group hover:border-heritage-gold/30 transition-all">
                      <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-1">
                           <label className="text-[9px] font-black uppercase text-gray-400">Display Label (ID)</label>
                           <input type="text" value={item.label.id} onChange={(e) => updateNavItem(item.id, {...item, label: {...item.label, id: e.target.value}})} className="input-field font-bold" placeholder="E.g. Beranda" />
                        </div>
                        <div className="space-y-1">
                           <label className="text-[9px] font-black uppercase text-gray-400">Target Link (Href)</label>
                           <input type="text" value={item.href} onChange={(e) => updateNavItem(item.id, {...item, href: e.target.value})} className="input-field" placeholder="#section" />
                        </div>
                      </div>
                      <button onClick={() => deleteNavItem(item.id)} className="text-red-400 p-3 hover:bg-red-50 rounded-xl transition-all self-end mb-1"><Trash2 className="w-5 h-5" /></button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* SECTION: ORGANIZATION */}
            {activeSection === 'organization' && (
              <div className="bg-white p-10 rounded-3xl shadow-sm border border-gray-200 space-y-10 animate-fade-in">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-heritage-gold/10 rounded-lg"><Users className="w-5 h-5 text-heritage-gold" /></div>
                  <h3 className="font-bold text-xs text-gray-400 uppercase tracking-[0.2em]">Official Organization</h3>
                </div>
                <div className="space-y-8">
                  <div className="space-y-2">
                    <label className="input-label">Official Vision Statement</label>
                    <textarea value={content.organization.vision.id} onChange={(e) => updateContent('organization', 'vision', e.target.value, 'id')} className="input-field h-32 leading-relaxed" placeholder="Tulis visi di sini..." />
                  </div>
                  <div className="space-y-2">
                    <label className="input-label">Official Mission Statement</label>
                    <textarea value={content.organization.mission.id} onChange={(e) => updateContent('organization', 'mission', e.target.value, 'id')} className="input-field h-40 leading-relaxed" placeholder="Tulis misi di sini..." />
                  </div>
                  <div className="space-y-2">
                    <label className="input-label">Brief Department Profile</label>
                    <textarea value={content.organization.profile.id} onChange={(e) => updateContent('organization', 'profile', e.target.value, 'id')} className="input-field h-52 leading-relaxed" placeholder="Profil dinas..." />
                  </div>
                  <div className="space-y-2">
                    <label className="input-label">Structure Chart Image URL</label>
                    <input type="text" value={content.organization.structureImageUrl} onChange={(e) => updateContent('organization', 'structureImageUrl', e.target.value)} className="input-field" placeholder="https://..." />
                  </div>
                </div>
              </div>
            )}

            {/* SECTION: SECTIONS (HERO/HISTORY/CULTURE) */}
            {activeSection === 'sections' && (
              <div className="space-y-10 animate-fade-in">
                {/* History Tangible */}
