                    <div className="p-2 bg-heritage-gold/10 rounded-lg"><FileText className="w-5 h-5 text-heritage-gold" /></div>
                    <h3 className="font-bold text-xs text-gray-400 uppercase tracking-[0.2em]">Warisan Benda (History Content)</h3>
                  </div>
                  <div className="space-y-6">
                    <div className="space-y-2">
                       <label className="input-label">Main Section Title</label>
                       <input type="text" value={content.history.title.id} onChange={(e) => updateContent('history', 'title', e.target.value, 'id')} className="input-field font-serif font-bold text-xl" />
                    </div>
                    <div className="space-y-2">
                       <label className="input-label">Primary Description Paragraph</label>
                       <textarea value={content.history.description1.id} onChange={(e) => updateContent('history', 'description1', e.target.value, 'id')} className="input-field h-32" />
                    </div>
                    <div className="space-y-2">
                       <label className="input-label">Secondary Description Paragraph</label>
                       <textarea value={content.history.description2.id} onChange={(e) => updateContent('history', 'description2', e.target.value, 'id')} className="input-field h-32" />
