                    <div className="space-y-2">
                       <label className="input-label">Feature Image URL</label>
                       <input type="text" value={content.history.imageUrl} onChange={(e) => updateContent('history', 'imageUrl', e.target.value)} className="input-field" placeholder="https://..." />
