                  </div>
                  {!editingNews && (
                    <button onClick={() => setEditingNews({ id: Date.now().toString(), title: {en:'',id:''}, date: new Date().toISOString().split('T')[0], summary: {en:'',id:''}, content: {en:'',id:''}, imageUrl: 'https://picsum.photos/800/600', imageUrls: [] })} className="btn-add">
