                  <h3 className="font-bold text-xs text-gray-400 uppercase tracking-[0.2em]">Public Contact & Location</h3>
                </div>
                <div className="space-y-2">
                  <label className="input-label">Physical Office Address</label>
                  <textarea value={content.contact.address} onChange={(e) => updateContent('contact', 'address', e.target.value)} className="input-field h-32 leading-relaxed" placeholder="Tulis alamat kantor di sini..." />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <label className="input-label">Official Phone</label>
                    <input type="text" value={content.contact.phone} onChange={(e) => updateContent('contact', 'phone', e.target.value)} className="input-field" placeholder="+62..." />
                  </div>
                  <div className="space-y-2">
                    <label className="input-label">Official Public Email</label>
                    <input type="text" value={content.contact.email} onChange={(e) => updateContent('contact', 'email', e.target.value)} className="input-field" placeholder="email@domain.com" />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="input-label">Google Maps Embed Embed URL</label>
                  <input type="text" value={content.contact.mapEmbedUrl} onChange={(e) => updateContent('contact', 'mapEmbedUrl', e.target.value)} className="input-field" placeholder="https://www.google.com/maps/embed?..." />
                  <p className="text-[10px] text-gray-400 italic mt-2">Pastikan URL diawali dengan 'https://www.google.com/maps/embed?'</p>
                </div>
              </div>
            )}

          </div>
        </div>
      </div>

      <style>{`
        .input-label { 
          display: block; 
          font-size: 0.65rem; 
          font-weight: 800; 
          color: #9ca3af; 
          text-transform: uppercase; 
          letter-spacing: 0.15em; 
          margin-bottom: 0.5rem; 
        }

        /* THE TEXTBOX MUST BE WHITE */
