  const [editingAttraction, setEditingAttraction] = useState<Attraction | null>(null);

  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);

  const triggerSaveFeedback = (id: string) => {
    setSaveStatus({ ...saveStatus, [id]: true });
    setTimeout(() => {
      setSaveStatus(prev => ({ ...prev, [id]: false }));
    }, 2000);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError(false);
    if(!login(loginIdentifier, loginPassword)) {
      setLoginError(true);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  };

  const onDragStart = (index: number) => setDraggedItemIndex(index);
  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedItemIndex === null || draggedItemIndex === index) return;
    const newItems = [...navItems];
    const draggedItem = newItems[draggedItemIndex];
    newItems.splice(draggedItemIndex, 1);
    newItems.splice(index, 0, draggedItem);
    reorderNavItems(newItems);
    setDraggedItemIndex(index);
  };
  const onDragEnd = () => setDraggedItemIndex(null);

  if (!isAdminOpen) return null;

  if (!isAuthenticated) {
