    e.preventDefault();
    if (draggedItemIndex === null || draggedItemIndex === index) return;
    const newItems = [...navItems];
    const draggedItem = newItems[draggedItemIndex];
    newItems.splice(draggedItemIndex, 1);
    newItems.splice(index, 0, draggedItem);
    reorderNavItems(newItems);
    setDraggedItemIndex(index);
  };
  const onDragEnd = () => setDraggedItemIndex(null);

  // Resize Handlers
  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => {
    setIsResizing(false);
  }, []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && containerRef.current) {
      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = containerRect.right - e.clientX;
      // Constraints: min 300px, max 80% of screen
      if (newWidth > 300 && newWidth < containerRect.width * 0.8) {
        setPreviewWidth(newWidth);
      }
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  // Calculate Scale Factor based on current width
  // Desktop content assumes a 1200px width normally.
  const getScaleFactor = () => {
    if (previewMode === 'mobile') {
      // If column is smaller than mobile frame (320px + padding), scale down
      const limit = 400;
      if (previewWidth < limit) return previewWidth / limit;
      return 1;
    } else {
      // Desktop: Scale the 1200px content to fit the available previewWidth (with padding)
      const padding = 80;
      const targetWidth = 1200;
      const factor = (previewWidth - padding) / targetWidth;
      return Math.min(factor, 1); // Don't scale up past 100%
    }
  };

