        @keyframes slide-in-right { from { opacity: 0; transform: translateX(50px); } to { opacity: 1; transform: translateX(0); } }
        .animate-slide-in-right { animation: slide-in-right 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }

        @keyframes scale-in { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .animate-scale-in { animation: scale-in 0.4s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }

        .preview-content {
           --color-primary: ${content.theme.primary};
           --color-secondary: ${content.theme.secondary};
           --color-background: ${content.theme.background};
           --color-dark: ${content.theme.dark};
           color: var(--color-dark);
           background-color: var(--color-background);
        }
      `}</style>
    </div>
  );
};

