              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Keamanan</label>
              <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="w-full px-6 py-4 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-heritage-gold transition-all text-sm" placeholder="Password" required />
            </div>
            <button type="submit" className="w-full bg-heritage-dark text-white font-bold py-4 rounded-xl hover:bg-heritage-gold transition-all shadow-xl uppercase tracking-[0.2em] text-xs mt-4">MASUK</button>
          </form>
        </div>
      </div>
    );
