const AdminPanel: React.FC = () => {
  const { 
    language, isAdminOpen, setIsAdminOpen, isAuthenticated, login, logout,
    content, updateContent, updateTheme, news, addNews, updateNews, deleteNews,
    navItems, addNavItem, updateNavItem, deleteNavItem, reorderNavItems,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addArtItem, updateArtItem, deleteArtItem
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isShaking, setIsShaking] = useState(false);
  const [activeSection, setActiveSection] = useState<string>('general');
  const [saveStatus, setSaveStatus] = useState<Record<string, boolean>>({});
  const [showPreview, setShowPreview] = useState(true);
  const [previewMode, setPreviewMode] = useState<'mobile' | 'desktop'>('mobile');

  // Resize and Zoom States
  const [previewWidth, setPreviewWidth] = useState(window.innerWidth > 1400 ? 550 : 450);
  const [isResizing, setIsResizing] = useState(false);
  const [manualZoom, setManualZoom] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);

  const triggerSaveFeedback = (id: string) => {
    setSaveStatus({ ...saveStatus, [id]: true });
    setTimeout(() => {
      setSaveStatus(prev => ({ ...prev, [id]: false }));
    }, 2000);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError(false);
    if(!login(loginIdentifier, loginPassword)) {
      setLoginError(true);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  };

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => {
    setIsResizing(false);
  }, []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && containerRef.current) {
      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = containerRect.right - e.clientX;
      if (newWidth > 320 && newWidth < containerRect.width * 0.8) {
        setPreviewWidth(newWidth);
      }
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  // Calculate Scale Factor based on current column width and manual zoom
  const getScaleFactor = () => {
    if (previewMode === 'mobile') {
      const mobileWidth = 320;
      const padding = 60;
      const autoScale = (previewWidth - padding) / mobileWidth;
      return Math.min(autoScale, 1) * manualZoom;
    } else {
      const desktopWidth = 1200;
      const padding = 80;
      const autoScale = (previewWidth - padding) / desktopWidth;
      return Math.min(autoScale, 1) * manualZoom;
    }
  };

  const resetZoom = () => setManualZoom(1);
  const zoomIn = () => setManualZoom(prev => Math.min(prev + 0.1, 2));
  const zoomOut = () => setManualZoom(prev => Math.max(prev - 0.1, 0.3));

  if (!isAdminOpen) return null;

  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-heritage-dark/95 backdrop-blur-md p-4 animate-fade-in">
        <div className={`bg-white rounded-3xl w-full max-w-md shadow-2xl relative p-10 transition-transform ${isShaking ? 'animate-shake' : ''}`}>
          <button onClick={() => setIsAdminOpen(false)} className="absolute top-6 right-6 text-gray-300 hover:text-red-500 p-2 transition-colors"><X className="w-6 h-6" /></button>
          <div className="text-center mb-10">
            <div className="w-16 h-16 bg-heritage-gold/10 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <Landmark className="w-8 h-8 text-heritage-gold" />
            </div>
            <h2 className="text-3xl font-serif font-bold text-heritage-dark">Portal Admin</h2>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mt-2">SAWAHLUNTO HERITAGE CMS</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input type="text" value={loginIdentifier} onChange={(e) => setLoginIdentifier(e.target.value)} className="w-full px-6 py-4 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-heritage-gold text-sm" placeholder="Username" required />
            <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="w-full px-6 py-4 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-heritage-gold text-sm" placeholder="Password" required />
            <button type="submit" className="w-full bg-heritage-dark text-white font-bold py-4 rounded-xl hover:bg-heritage-gold transition-all shadow-xl uppercase tracking-[0.2em] text-xs">MASUK</button>
          </form>
        </div>
      </div>
    );
  }

  const SaveButton = ({ id }: { id: string }) => (
    <button 
      onClick={() => triggerSaveFeedback(id)}
      className={`mt-6 w-full flex items-center justify-center gap-2 py-3.5 rounded-xl font-bold uppercase tracking-widest text-[10px] transition-all duration-300 ${
        saveStatus[id] ? 'bg-green-500 text-white' : 'bg-heritage-dark text-white hover:bg-heritage-gold shadow-lg hover:shadow-heritage-gold/20'
      }`}
    >
      {saveStatus[id] ? <CheckCircle className="w-4 h-4 animate-bounce" /> : <Save className="w-4 h-4" />}
      {saveStatus[id] ? t.saved[language] : t.save[language]}
