               <div className="sticky bottom-4 bg-white/80 backdrop-blur px-4 py-2 rounded-full border border-gray-200 shadow-sm text-[8px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 animate-bounce">
                  <GripHorizontal className="w-3 h-3" /> Geser tepi untuk mengubah ukuran
               </div>
