          )}
        </div>
      </div>

      <style>{`
        .input-label { display: block; font-size: 0.65rem; font-weight: 800; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.15em; margin-bottom: 0.8rem; }
        .input-field { width: 100%; background-color: #f9fafb !important; border: 1px solid #e5e7eb; padding: 1rem 1.25rem; border-radius: 1.25rem; font-size: 0.875rem; color: #1a1a1a; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
        .input-field:focus { outline: none; border-color: #C5A059; background-color: #fff !important; box-shadow: 0 0 0 5px rgba(197, 160, 89, 0.1); transform: translateY(-1px); }
