                      </div>
                   </div>
                   <SaveButton id="heritage-save" />
                </div>
              )}

              {/* SECTION: NEWS */}
              {activeSection === 'news' && (
                <div className="space-y-10 animate-fade-in">
                   <div className="flex justify-between items-center">
                      <SectionTitle icon={Instagram} title="Daftar Berita" subtitle="Kelola artikel dan pengumuman terbaru" />
                      <button onClick={() => addNews({ id: Date.now().toString(), date: new Date().toISOString().split('T')[0], title: {en:'New News', id:'Berita Baru'}, summary: {en:'',id:''}, content: {en:'',id:''}, imageUrl: 'https://picsum.photos/400/300' })} className="bg-heritage-gold text-white px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2"><Plus className="w-3 h-3" /> Tambah Berita</button>
                   </div>
                   <div className="grid grid-cols-1 gap-6">
                      {news.map(item => (
                        <div key={item.id} className="bg-gray-50 p-6 rounded-3xl border border-gray-200 flex gap-6 group hover:border-heritage-gold transition-colors">
                           <div className="w-32 h-32 rounded-2xl overflow-hidden shrink-0 border border-gray-200">
                             <img src={item.imageUrl} alt="" className="w-full h-full object-cover" />
                           </div>
                           <div className="flex-1 space-y-3">
                             <div className="flex justify-between">
                                <input type="text" value={item.title.id} onChange={(e) => updateNews(item.id, {...item, title: {...item.title, id: e.target.value}})} className="bg-transparent font-bold text-heritage-dark focus:outline-none focus:text-heritage-gold w-full" />
                                <button onClick={() => deleteNews(item.id)} className="text-red-300 hover:text-red-500 p-2"><Trash2 className="w-4 h-4" /></button>
