                             <input type="date" value={item.date} onChange={(e) => updateNews(item.id, {...item, date: e.target.value})} className="bg-white border border-gray-200 rounded-lg px-3 py-1 text-[10px] font-bold text-gray-400 uppercase tracking-widest focus:outline-none" />
