                      <div className="space-y-2">
                        <label className="input-label">Jam Operasional (ID)</label>
                        <input type="text" value={content.tickets.openingHours.id} onChange={(e) => updateContent('tickets', 'openingHours', e.target.value, 'id')} className="input-field" />
                      </div>

                      <div className="border-t border-gray-200 pt-6 space-y-4">
                        <div className="flex justify-between items-center">
                           <h4 className="text-[10px] font-black uppercase text-heritage-dark tracking-widest">Daftar Kategori Tiket</h4>
                           <button onClick={() => addTicket({ id: Date.now().toString(), title: {en:'Child', id:'Anak'}, category: {en:'Local', id:'Lokal'}, price: 5000, imageUrl: 'https://picsum.photos/400/200' })} className="text-heritage-gold font-bold text-[10px] uppercase tracking-widest hover:underline">+ Tambah Tiket</button>
                        </div>
                        <div className="space-y-3">
                           {content.tickets.items.map(t => (
