                                <input type="text" value={t.category.id} onChange={(e) => updateTicket(t.id, {...t, category: {...t.category, id: e.target.value}})} className="input-field text-xs w-1/4" placeholder="Kategori" />
                                <button onClick={() => deleteTicket(t.id)} className="p-2 text-red-300 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
