                   <SectionTitle icon={Phone} title="Informasi Kontak" subtitle="Alamat, telepon, dan peta lokasi" />
                   <div className="bg-gray-50 p-8 rounded-3xl border border-gray-200 space-y-6">
                      <div className="space-y-4">
                         <div>
                            <label className="input-label">Alamat Lengkap</label>
                            <textarea value={content.contact.address} onChange={(e) => updateContent('contact', 'address', e.target.value)} className="input-field min-h-[80px]" />
                         </div>
                         <div className="grid grid-cols-2 gap-6">
                            <div>
                               <label className="input-label">Telepon</label>
                               <input type="text" value={content.contact.phone} onChange={(e) => updateContent('contact', 'phone', e.target.value)} className="input-field" />
                            </div>
                            <div>
                               <label className="input-label">Email</label>
                               <input type="text" value={content.contact.email} onChange={(e) => updateContent('contact', 'email', e.target.value)} className="input-field" />
                            </div>
                         </div>
                         <div>
                            <label className="input-label">Google Maps Embed URL</label>
                            <input type="text" value={content.contact.mapEmbedUrl} onChange={(e) => updateContent('contact', 'mapEmbedUrl', e.target.value)} className="input-field font-mono text-[10px]" />
                         </div>
                      </div>
                   </div>
                   <SaveButton id="contact-save" />
                </div>
              )}

              {/* Fallback for undeveloped sections */}
              {!['general', 'theme', 'navigation', 'heritage', 'news', 'tickets', 'contact'].includes(activeSection) && (
                <div className="flex flex-col items-center justify-center py-32 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200 text-gray-300">
                   <Hash className="w-12 h-12 mb-4 opacity-10" />
                   <p className="font-bold text-xs uppercase tracking-widest">Section {activeSection} sedang dalam pengembangan</p>
                </div>
              )}
            </div>
          </div>

          {/* DRAGGABLE RESIZER */}
          {showPreview && (
            <div 
              onMouseDown={startResizing} 
              className={`w-1.5 bg-gray-100 hover:bg-heritage-gold cursor-col-resize z-[40] transition-colors relative flex items-center justify-center ${isResizing ? 'bg-heritage-gold' : ''}`}
            >
               <div className="absolute top-1/2 -translate-y-1/2 w-4 h-10 bg-white border border-gray-200 rounded-full shadow-md flex items-center justify-center -translate-x-1/2">
                  <GripVertical className="w-3 h-3 text-gray-400" />
               </div>
            </div>
          )}

          {/* LIVE DESKTOP PREVIEW */}
          {showPreview && (
            <div 
              style={{ width: `${previewWidth}px` }} 
              className="bg-gray-100 flex flex-col items-center overflow-hidden relative shrink-0 border-l border-gray-200 workspace-grid"
            >
               {/* Controls Bar */}
               <div className="sticky top-0 w-full p-4 bg-white/90 backdrop-blur-md border-b border-gray-200 z-[50] flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-3">
                     <div className="p-2.5 bg-heritage-gold/10 rounded-xl text-heritage-gold shadow-inner">
                        <Monitor className="w-4 h-4" />
                     </div>
                     <span className="text-[10px] font-black uppercase tracking-widest text-heritage-dark">Desktop Simulator</span>
                  </div>

                  <div className="flex items-center gap-3 bg-gray-100 px-3 py-1.5 rounded-xl border border-gray-200">
                     <button onClick={() => setManualZoom(prev => Math.max(prev - 0.1, 0.2))} className="text-gray-500 hover:text-heritage-gold p-1 transition-colors"><ZoomOut className="w-4 h-4" /></button>
                     <div className="flex flex-col items-center w-12 group cursor-pointer" onClick={() => setManualZoom(1)}>
                        <span className="text-[9px] font-mono font-bold text-heritage-dark">{Math.round(getScaleFactor() * 100)}%</span>
                        <span className="text-[7px] font-bold text-gray-400 uppercase hidden group-hover:block">Fit</span>
                     </div>
                     <button onClick={() => setManualZoom(prev => Math.min(prev + 0.1, 2.0))} className="text-gray-500 hover:text-heritage-gold p-1 transition-colors"><ZoomIn className="w-4 h-4" /></button>
                  </div>
               </div>

               {/* Preview Content Area */}
               <div className="flex-1 w-full flex items-start justify-center overflow-auto custom-scrollbar p-10">
                  <div 
                    className="relative origin-top transition-transform duration-300 ease-out shadow-[0_40px_120px_rgba(0,0,0,0.3)]"
                    style={{ 
                        transform: `scale(${getScaleFactor()})`,
                        width: '1280px',
                        minHeight: '1500px'
                    }}
                  >
                    {/* Browser Shell */}
                    <div className="bg-white overflow-hidden flex flex-col h-full border border-gray-200 rounded-2xl shadow-2xl h-full">
                        <div className="h-12 bg-gray-50 border-b border-gray-200 flex items-center gap-3 px-6 shrink-0">
                           <div className="flex gap-1.5"><div className="w-3 h-3 bg-red-400 rounded-full" /><div className="w-3 h-3 bg-yellow-400 rounded-full" /><div className="w-3 h-3 bg-green-400 rounded-full" /></div>
                           <div className="flex-1 bg-white mx-4 rounded-lg border border-gray-200 px-4 py-1.5 text-[9px] font-mono text-gray-400 truncate flex items-center gap-2">
                             <Lock className="w-2.5 h-2.5" /> https://heritage.sawahluntokota.go.id
                           </div>
                           <div className="flex gap-2 text-gray-300"><ChevronLeft className="w-4 h-4" /><ChevronRight className="w-4 h-4" /><RefreshCw className="w-3 h-3" /></div>
                        </div>

                        <div className="flex-1 overflow-y-auto hide-scrollbar preview-content" style={{ 
                            '--color-primary': content.theme.primary,
                            '--color-secondary': content.theme.secondary,
                            '--color-background': content.theme.background,
                            '--color-dark': content.theme.dark,
                        } as React.CSSProperties}>
                           <div className="pointer-events-none">
                             <Hero />
                             <MuseumMap />
                             <ExternalPortals />
                             <HeritageMain />
                             <ArtsSection />
                             <NewsSection />
                             <Attractions />
                             <InfoSection />
                             <Footer />
                           </div>
                        </div>
                    </div>
                  </div>
               </div>

               <div className="sticky bottom-6 bg-heritage-dark text-white px-5 py-2.5 rounded-full border border-white/10 shadow-2xl text-[9px] font-black uppercase tracking-[0.2em] flex items-center gap-3 animate-bounce">
                  <GripHorizontal className="w-4 h-4 text-heritage-gold" /> Geser tepi kolom untuk mengubah skala
               </div>
            </div>
          )}
        </div>
      </div>

      <style>{`
        .input-label { display: block; font-size: 0.65rem; font-weight: 800; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.15em; margin-bottom: 0.6rem; }
        .input-field { width: 100%; background-color: #f9fafb !important; border: 1px solid #e5e7eb; padding: 0.85rem 1.25rem; border-radius: 1rem; font-size: 0.875rem; color: #1a1a1a; transition: all 0.2s ease; }
        .input-field:focus { outline: none; border-color: #C5A059; background-color: #fff !important; box-shadow: 0 0 0 4px rgba(197, 160, 89, 0.1); }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #C5A059; }
        .workspace-grid { background-image: radial-gradient(#cbd5e1 0.7px, transparent 0.7px); background-size: 30px 30px; }
        .preview-content {
           color: var(--color-dark);
           background-color: var(--color-background);
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-10px); }
          75% { transform: translateX(10px); }
        }
        .animate-shake { animation: shake 0.4s ease-in-out; }
      `}</style>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useData } from '../contexts/DataContext';
import { 
  X, Plus, Trash2, Edit2, Globe, Palette, Users, FileText, Music, Instagram, 
  Phone, Ticket, MapPin, Navigation, Layout, User as UserIcon, Key, 
  AlertTriangle, Save, PlusCircle, ArrowUp, ArrowDown, Link as LinkIcon, 
  Image as ImageIcon, CheckCircle, Info, Landmark, Calendar, Clock, Camera,
  GripVertical, Eye, EyeOff, Monitor, ChevronLeft, ChevronRight, RefreshCw,
  GripHorizontal, Maximize, ZoomIn, ZoomOut, Lock, Settings, Target, Hash,
  Images
} from 'lucide-react';

// Import public components for preview
import Hero from './Hero';
import HeritageMain from './HeritageMain';
import ArtsSection from './ArtsSection';
import Attractions from './Attractions';
import NewsSection from './NewsSection';
import InfoSection from './InfoSection';
import Footer from './Footer';
import MuseumMap from './MuseumMap';
import ExternalPortals from './ExternalPortals';

const t = {
  adminPortal: { en: 'Admin Portal', id: 'Portal Admin' },
  cmsName: { en: 'Sawahlunto Heritage CMS', id: 'CMS Warisan Sawahlunto' },
  save: { en: 'Save Changes', id: 'Simpan Perubahan' },
  saved: { en: 'Saved!', id: 'Tersimpan!' },
  logout: { en: 'Logout', id: 'Keluar' },
};

const AdminPanel: React.FC = () => {
  const { 
    language, isAdminOpen, setIsAdminOpen, isAuthenticated, login, logout,
    content, updateContent, updateTheme, 
    navItems, addNavItem, updateNavItem, deleteNavItem,
    news, addNews, updateNews, deleteNews,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addArtItem, updateArtItem, deleteArtItem,
    addTicket, updateTicket, deleteTicket
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isShaking, setIsShaking] = useState(false);
  const [activeSection, setActiveSection] = useState<string>('general');
  const [saveStatus, setSaveStatus] = useState<Record<string, boolean>>({});
  const [showPreview, setShowPreview] = useState(true);

  const [previewWidth, setPreviewWidth] = useState(window.innerWidth > 1400 ? 750 : 600);
  const [isResizing, setIsResizing] = useState(false);
  const [manualZoom, setManualZoom] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);

  const triggerSaveFeedback = (id: string) => {
    setSaveStatus({ ...saveStatus, [id]: true });
    setTimeout(() => setSaveStatus(prev => ({ ...prev, [id]: false })), 2000);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if(!login(loginIdentifier, loginPassword)) {
      setLoginError(true);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  };

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && containerRef.current) {
      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = containerRect.right - e.clientX;
      if (newWidth > 320 && newWidth < containerRect.width * 0.85) setPreviewWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  const getScaleFactor = () => {
    const desktopBaseWidth = 1280;
    const padding = 60; 
    const autoScale = (previewWidth - padding) / desktopBaseWidth;
    return Math.min(autoScale, 1.5) * manualZoom;
  };

  if (!isAdminOpen) return null;

  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-heritage-dark/95 backdrop-blur-md p-4 animate-fade-in">
        <div className={`bg-white rounded-3xl w-full max-w-md shadow-2xl relative p-10 transition-transform ${isShaking ? 'animate-shake' : ''}`}>
          <button onClick={() => setIsAdminOpen(false)} className="absolute top-6 right-6 text-gray-300 hover:text-red-500 p-2 transition-colors"><X className="w-6 h-6" /></button>
          <div className="text-center mb-10">
            <div className="w-16 h-16 bg-heritage-gold/10 rounded-2xl flex items-center justify-center mx-auto mb-4"><Landmark className="w-8 h-8 text-heritage-gold" /></div>
            <h2 className="text-3xl font-serif font-bold text-heritage-dark">{t.adminPortal[language]}</h2>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mt-2">{t.cmsName[language]}</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input type="text" value={loginIdentifier} onChange={(e) => setLoginIdentifier(e.target.value)} className="w-full px-6 py-4 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-heritage-gold text-sm" placeholder="Username" required />
            <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="w-full px-6 py-4 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-heritage-gold text-sm" placeholder="Password" required />
            <button type="submit" className="w-full bg-heritage-dark text-white font-bold py-4 rounded-xl hover:bg-heritage-gold transition-all shadow-xl uppercase tracking-[0.2em] text-xs">MASUK</button>
          </form>
        </div>
      </div>
    );
  }

  const SectionTitle = ({ icon: Icon, title, subtitle }: any) => (
    <div className="mb-8 border-b border-gray-100 pb-6">
      <div className="flex items-center gap-3 mb-2">
        <div className="bg-heritage-gold/10 p-2 rounded-xl text-heritage-gold"><Icon className="w-5 h-5" /></div>
        <h3 className="text-xl font-serif font-bold text-heritage-dark">{title}</h3>
      </div>
      <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{subtitle}</p>
    </div>
  );

  const SaveButton = ({ id }: { id: string }) => (
    <button 
      onClick={() => triggerSaveFeedback(id)}
      className={`mt-10 w-full flex items-center justify-center gap-2 py-4 rounded-xl font-bold uppercase tracking-widest text-xs transition-all duration-300 shadow-lg ${
        saveStatus[id] ? 'bg-green-500 text-white' : 'bg-heritage-dark text-white hover:bg-heritage-gold'
      }`}
    >
      {saveStatus[id] ? <CheckCircle className="w-4 h-4 animate-bounce" /> : <Save className="w-4 h-4" />}
      {saveStatus[id] ? t.saved[language] : t.save[language]}
    </button>
  );

  const sidebarLinks = [
    { id: 'general', label: 'Identitas', icon: Globe },
    { id: 'theme', label: 'Tampilan', icon: Palette },
    { id: 'navigation', label: 'Menu Navigasi', icon: Navigation },
    { id: 'organization', label: 'Organisasi', icon: Users },
    { id: 'heritage', label: 'Konten Warisan', icon: FileText },
    { id: 'arts', label: 'Seni & Budaya', icon: Music },
    { id: 'news', label: 'Berita', icon: Instagram },
    { id: 'destinations', label: 'Destinasi', icon: MapPin },
    { id: 'tickets', label: 'Tiket & Jam', icon: Ticket },
    { id: 'contact', label: 'Kontak', icon: Phone },
  ];

  return (
    <div className="fixed inset-0 z-[100] flex bg-gray-100 font-sans overflow-hidden" ref={containerRef}>
      {/* Sidebar */}
      <div className="w-72 bg-white border-r border-gray-200 flex flex-col h-full shadow-2xl z-20">
        <div className="p-8 border-b border-gray-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="bg-heritage-dark text-white p-2 rounded-lg"><Settings className="w-5 h-5" /></div>
            <h2 className="font-serif font-bold text-xl tracking-tight">DASHBOARD</h2>
          </div>
          <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Heritage CMS v2.0</p>
        </div>
        <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-1 custom-scrollbar">
          {sidebarLinks.map(link => (
            <button key={link.id} onClick={() => setActiveSection(link.id)} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${activeSection === link.id ? 'bg-heritage-dark text-white shadow-xl' : 'text-gray-500 hover:bg-gray-50'}`}>
              <link.icon className={`w-4 h-4 ${activeSection === link.id ? 'text-heritage-gold' : ''}`} />
              {link.label}
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-gray-100">
          <button onClick={logout} className="w-full flex items-center justify-center gap-2 py-3.5 bg-red-50 text-red-600 rounded-xl font-bold text-[10px] uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all"><Lock className="w-4 h-4" /> {t.logout[language]}</button>
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full bg-white overflow-hidden">
        <header className="h-20 bg-white border-b border-gray-100 px-10 flex items-center justify-between z-10">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsAdminOpen(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-6 h-6 text-gray-400" /></button>
            <h1 className="font-serif font-bold text-2xl text-heritage-dark uppercase">{activeSection}</h1>
          </div>
          <button onClick={() => setShowPreview(!showPreview)} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${showPreview ? 'bg-heritage-gold text-white shadow-lg' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}>{showPreview ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />} Preview</button>
        </header>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 overflow-y-auto p-12 custom-scrollbar bg-white">
            <div className="max-w-3xl mx-auto">
              {/* BRANDING */}
              {activeSection === 'general' && (
                <div className="space-y-10">
                  <SectionTitle icon={Globe} title="Identitas & Logo" subtitle="Pengaturan branding situs utama" />
