                <div className="sticky top-0 w-full p-4 bg-white/90 backdrop-blur-md border-b border-gray-200 z-[50] flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-3"><div className="p-2 bg-heritage-gold/10 rounded-xl text-heritage-gold shadow-inner"><Monitor className="w-4 h-4" /></div><span className="text-[10px] font-black uppercase tracking-widest text-heritage-dark">Desktop Simulator</span></div>
                    <div className="flex items-center gap-3 bg-gray-100 px-3 py-1.5 rounded-xl border border-gray-200">
                       <button onClick={() => setManualZoom(prev => Math.max(prev - 0.1, 0.2))} className="text-gray-500 hover:text-heritage-gold p-1 transition-colors"><ZoomOut className="w-4 h-4" /></button>
                       <div className="flex flex-col items-center w-12 group cursor-pointer" onClick={() => setManualZoom(1)}><span className="text-[9px] font-mono font-bold text-heritage-dark">{Math.round(getScaleFactor() * 100)}%</span><span className="text-[7px] font-bold text-gray-400 uppercase hidden group-hover:block">Fit</span></div>
                       <button onClick={() => setManualZoom(prev => Math.min(prev + 0.1, 2.0))} className="text-gray-500 hover:text-heritage-gold p-1 transition-colors"><ZoomIn className="w-4 h-4" /></button>
                    </div>
