                <div className="flex-1 w-full flex items-start justify-center overflow-auto custom-scrollbar p-10">
                   <div className="relative origin-top transition-transform duration-300 ease-out shadow-[0_40px_120px_rgba(0,0,0,0.3)]" style={{ transform: `scale(${getScaleFactor()})`, width: '1280px', minHeight: '1500px' }}>
                     <div className="bg-white overflow-hidden flex flex-col h-full border border-gray-200 rounded-2xl shadow-2xl h-full">
                        <div className="h-12 bg-gray-50 border-b border-gray-200 flex items-center gap-3 px-6 shrink-0">
                           <div className="flex gap-1.5"><div className="w-3 h-3 bg-red-400 rounded-full" /><div className="w-3 h-3 bg-yellow-400 rounded-full" /><div className="w-3 h-3 bg-green-400 rounded-full" /></div>
                           <div className="flex-1 bg-white mx-4 rounded-lg border border-gray-200 px-4 py-1.5 text-[9px] font-mono text-gray-400 truncate flex items-center gap-2"><Lock className="w-2.5 h-2.5" /> https://heritage.sawahluntokota.go.id</div>
                           <div className="flex gap-2 text-gray-300"><ChevronLeft className="w-4 h-4" /><ChevronRight className="w-4 h-4" /><RefreshCw className="w-3 h-3" /></div>
