                        </div>
                     </div>
                   </div>
                </div>
                <div className="sticky bottom-6 bg-white/80 backdrop-blur-md text-heritage-dark px-5 py-2 rounded-full border border-gray-200 shadow-xl text-[8px] font-black uppercase tracking-widest flex items-center gap-2.5 opacity-60 hover:opacity-100 transition-opacity"><GripHorizontal className="w-3.5 h-3.5 text-heritage-gold" /> Geser tepi untuk skala</div>
