          <h2 className="font-serif font-black text-xl tracking-tighter text-heritage-dark">CMS PORTAL</h2>
          <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest mt-1">V2.1 Standard Edition</p>
        </div>
        <nav className="flex-1 overflow-y-auto py-8 px-5 space-y-1.5 custom-scrollbar">
          {sidebarLinks.map((link, idx) => (
            <button 
              key={link.id} 
              onClick={() => setActiveSection(link.id)} 
              className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.15em] transition-all border ${
                activeSection === link.id 
                ? 'bg-heritage-dark border-heritage-dark text-white shadow-xl translate-x-1' 
                : 'bg-transparent border-transparent text-gray-400 hover:bg-gray-50 hover:border-gray-100 hover:text-heritage-dark'
              }`}
            >
              <link.icon className={`w-4 h-4 ${activeSection === link.id ? 'text-heritage-gold' : 'opacity-40'}`} />
              {link.label}
              {activeSection === link.id && <div className="ml-auto w-1.5 h-1.5 bg-heritage-gold rounded-full shadow-[0_0_10px_#C5A059]"></div>}
            </button>
          ))}
        </nav>
        <div className="p-8 border-t border-gray-100 bg-gray-50/50">
          <button onClick={logout} className="w-full flex items-center justify-center gap-3 py-3.5 bg-white text-gray-400 border border-gray-200 rounded-2xl font-black text-[9px] uppercase tracking-widest hover:bg-red-50 hover:text-red-500 hover:border-red-100 transition-all shadow-sm">
            <Lock className="w-3.5 h-3.5" /> {t.logout[language]}
