              {/* ORGANIZATION CARD */}
              {activeSection === 'organization' && (
                <div className="space-y-12 animate-fade-in">
                   <SectionTitle icon={Users} title="Profil Organisasi" subtitle="Visi, misi, dan tata kelola" />
