                      <div className="space-y-8">
                         <div className="space-y-3"><label className="input-label flex items-center gap-2"><Target className="w-4 h-4 text-heritage-gold" /> Visi Organisasi</label><textarea value={content.organization.vision.id} onChange={(e) => updateContent('organization', 'vision', e.target.value, 'id')} className="input-field italic font-serif text-lg py-6" /></div>
                         <div className="h-px bg-gray-100"></div>
                         <div className="space-y-3"><label className="input-label">Misi Organisasi</label><textarea value={content.organization.mission.id} onChange={(e) => updateContent('organization', 'mission', e.target.value, 'id')} className="input-field min-h-[150px] leading-relaxed" /></div>
                         <div className="h-px bg-gray-100"></div>
                         <div className="space-y-3"><label className="input-label">Profil Institusi</label><textarea value={content.organization.profile.id} onChange={(e) => updateContent('organization', 'profile', e.target.value, 'id')} className="input-field min-h-[180px]" /></div>
                         <div className="h-px bg-gray-100"></div>
                         <div className="space-y-4">
                            <label className="input-label">Bagan Struktur Organisasi (Image Link)</label>
                            <div className="flex gap-6 items-center">
                               <input type="text" value={content.organization.structureImageUrl} onChange={(e) => updateContent('organization', 'structureImageUrl', e.target.value)} className="input-field font-mono text-xs" placeholder="https://..." />
                               <div className="w-20 h-20 bg-gray-50 border border-gray-200 rounded-2xl flex items-center justify-center shrink-0 overflow-hidden shadow-inner">
                                  {content.organization.structureImageUrl ? <img src={content.organization.structureImageUrl} className="max-w-full max-h-full object-contain" /> : <Users className="w-6 h-6 text-gray-200" />}
                               </div>
                            </div>
                         </div>
                      </div>
                      <SaveButton id="org-save" />
                   </div>
                </div>
              )}

              {/* Fallback for sections under development */}
              {!['general', 'theme', 'navigation', 'heritage', 'news', 'tickets', 'contact', 'arts', 'destinations', 'organization'].includes(activeSection) && (
                <div className="flex flex-col items-center justify-center py-40 bg-white rounded-[3rem] border border-gray-100 border-dashed text-gray-300">
                   <div className="p-6 bg-gray-50 rounded-full mb-6 border border-gray-100 shadow-inner">
                      <Hash className="w-10 h-10 opacity-20" />
                   </div>
                   <p className="font-black text-xs uppercase tracking-[0.3em] text-gray-400">Editor {activeSection} Tersedia Segera</p>
                </div>
              )}
            </div>
          </div>

          {/* PREVIEW CONTAINER */}
          {showPreview && (
            <>
              {/* DRAGGABLE DIVIDER */}
              <div onMouseDown={startResizing} className={`w-1.5 bg-gray-50 hover:bg-heritage-gold cursor-col-resize z-[40] transition-colors relative flex items-center justify-center border-l border-gray-100 ${isResizing ? 'bg-heritage-gold shadow-[0_0_20px_#C5A059]' : ''}`}>
                 <div className="absolute top-1/2 -translate-y-1/2 w-4 h-12 bg-white border border-gray-200 rounded-full shadow-lg flex flex-col gap-1 items-center justify-center -translate-x-1/2">
                    <div className="w-0.5 h-0.5 bg-gray-300 rounded-full"></div>
                    <div className="w-0.5 h-0.5 bg-gray-300 rounded-full"></div>
                    <div className="w-0.5 h-0.5 bg-gray-300 rounded-full"></div>
                 </div>
              </div>

              {/* DESKTOP PREVIEW AREA */}
              <div style={{ width: `${previewWidth}px` }} className="bg-[#EDF1F7] flex flex-col items-center overflow-hidden relative shrink-0 border-l border-gray-200 workspace-grid">
                <div className="sticky top-0 w-full p-5 bg-white/95 backdrop-blur-md border-b border-gray-200 z-[50] flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-3">
                       <div className="p-2 bg-heritage-gold/10 rounded-xl text-heritage-gold border border-heritage-gold/20 shadow-inner"><Monitor className="w-4 h-4" /></div>
                       <span className="text-[10px] font-black uppercase tracking-widest text-heritage-dark opacity-70">Desktop Environment</span>
                    </div>
                    <div className="flex items-center gap-3 bg-white px-4 py-2 rounded-full border border-gray-200 shadow-sm">
                       <button onClick={() => setManualZoom(prev => Math.max(prev - 0.1, 0.2))} className="text-gray-400 hover:text-heritage-gold p-1 transition-colors"><ZoomOut className="w-4 h-4" /></button>
                       <div className="w-px h-4 bg-gray-100 mx-1"></div>
                       <div className="flex flex-col items-center w-12 cursor-pointer group" onClick={() => setManualZoom(1)}>
                          <span className="text-[9px] font-mono font-black text-heritage-dark">{Math.round(getScaleFactor() * 100)}%</span>
                          <span className="text-[6px] font-bold text-heritage-gold hidden group-hover:block">RESET</span>
                       </div>
                       <div className="w-px h-4 bg-gray-100 mx-1"></div>
                       <button onClick={() => setManualZoom(prev => Math.min(prev + 0.1, 2.0))} className="text-gray-400 hover:text-heritage-gold p-1 transition-colors"><ZoomIn className="w-4 h-4" /></button>
                    </div>
                </div>

                <div className="flex-1 w-full flex items-start justify-center overflow-auto custom-scrollbar p-12">
                   <div 
                     className="relative origin-top transition-transform duration-300 ease-out shadow-[0_50px_150px_rgba(0,0,0,0.12)] border border-white/50 rounded-2xl" 
                     style={{ 
                        transform: `scale(${getScaleFactor()})`, 
                        width: '1280px', 
                        minHeight: '1800px',
                        marginTop: '20px'
                     }}
                   >
                     {/* BROWSER MOCKUP */}
                     <div className="bg-white overflow-hidden flex flex-col h-full border-4 border-[#1A1A1A] rounded-2xl shadow-2xl h-full">
                        <div className="h-12 bg-[#1A1A1A] flex items-center gap-4 px-6 shrink-0">
                           <div className="flex gap-2"><div className="w-3 h-3 bg-[#FF5F57] rounded-full" /><div className="w-3 h-3 bg-[#FEBC2E] rounded-full" /><div className="w-3 h-3 bg-[#28C840] rounded-full" /></div>
                           <div className="flex-1 bg-white/10 mx-6 rounded-lg px-4 py-1.5 text-[9px] font-mono text-white/40 truncate flex items-center gap-3 border border-white/5">
                              <Lock className="w-3 h-3 text-heritage-gold" /> heritage.sawahlunto.go.id/portal
                           </div>
                           <div className="flex gap-4 text-white/30"><ChevronLeft className="w-4 h-4" /><ChevronRight className="w-4 h-4" /><RefreshCw className="w-3.5 h-3.5" /></div>
                        </div>
                        <div className="flex-1 overflow-y-auto hide-scrollbar preview-content" style={{ '--color-primary': content.theme.primary, '--color-secondary': content.theme.secondary, '--color-background': content.theme.background, '--color-dark': content.theme.dark } as React.CSSProperties}>
                           <div className="pointer-events-none origin-top transition-all">
                              <Hero />
                              <MuseumMap />
                              <ExternalPortals />
                              <HeritageMain />
                              <ArtsSection />
                              <NewsSection />
                              <Attractions />
                              <InfoSection />
                              <Footer />
                           </div>
                        </div>
                     </div>
                   </div>
                </div>

                <div className="sticky bottom-8 bg-white/90 backdrop-blur-md text-heritage-dark px-6 py-3 rounded-full border border-gray-200 shadow-2xl text-[9px] font-black uppercase tracking-[0.25em] flex items-center gap-3 opacity-80 hover:opacity-100 transition-all cursor-default">
                   <GripHorizontal className="w-4 h-4 text-heritage-gold" /> Geser divider untuk zoom dinamis
                </div>
              </div>
            </>
          )}
        </div>
      </div>
      <style>{`
        .input-label { display: block; font-size: 0.65rem; font-weight: 900; color: #94A3B8; text-transform: uppercase; letter-spacing: 0.25em; margin-bottom: 0.6rem; }
        .input-field { width: 100%; background-color: #F8FAFC !important; border: 1.5px solid #F1F5F9; padding: 1rem 1.25rem; border-radius: 1.25rem; font-size: 0.85rem; color: #1E293B; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); shadow: inset 0 2px 4px rgba(0,0,0,0.02); }
        .input-field:focus { outline: none; border-color: #C5A059; background-color: #FFF !important; box-shadow: 0 0 0 5px rgba(197, 160, 89, 0.1); transform: translateY(-1px); }
        .btn-add { background: #FFF; color: #1E293B; padding: 0.65rem 1.5rem; border-radius: 1.25rem; font-size: 0.65rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.15em; display: flex; align-items: center; gap: 0.5rem; transition: all 0.3s ease; border: 1.5px solid #F1F5F9; }
        .btn-add:hover { background: #C5A059; color: white; border-color: #C5A059; transform: translateY(-2px); }
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #E2E8F0; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #C5A059; }
        .workspace-grid { background-image: radial-gradient(#CBD5E1 0.8px, transparent 0.8px); background-size: 24px 24px; }
        .preview-content { color: var(--color-dark); background-color: var(--color-background); }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-8px); } 75% { transform: translateX(8px); } }
        .animate-shake { animation: shake 0.4s ease-in-out; }
      `}</style>
    </div>
  );
};

