import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useData } from '../contexts/DataContext';
import { 
  X, Plus, Trash2, Edit2, Globe, Palette, Users, FileText, Music, Instagram, 
  Phone, Ticket, MapPin, Navigation, Layout, User as UserIcon, Key, 
  AlertTriangle, Save, PlusCircle, ArrowUp, ArrowDown, Link as LinkIcon, 
  Image as ImageIcon, CheckCircle, Info, Landmark, Calendar, Clock, Camera,
  GripVertical, Eye, EyeOff, Monitor, ChevronLeft, ChevronRight, RefreshCw,
  GripHorizontal, Maximize, ZoomIn, ZoomOut, Lock, Settings, Target, Hash,
  Images
} from 'lucide-react';

// Import public components for preview
import Hero from './Hero';
import HeritageMain from './HeritageMain';
import ArtsSection from './ArtsSection';
import Attractions from './Attractions';
import NewsSection from './NewsSection';
import InfoSection from './InfoSection';
import Footer from './Footer';
import MuseumMap from './MuseumMap';
import ExternalPortals from './ExternalPortals';

const t = {
  adminPortal: { en: 'Admin Portal', id: 'Portal Admin' },
  cmsName: { en: 'Sawahlunto Heritage CMS', id: 'CMS Warisan Sawahlunto' },
  save: { en: 'Save Changes', id: 'Simpan' },
  saved: { en: 'Success!', id: 'Berhasil!' },
  logout: { en: 'Logout', id: 'Keluar' },
};

const AdminPanel: React.FC = () => {
  const { 
    language, isAdminOpen, setIsAdminOpen, isAuthenticated, login, logout,
    content, updateContent, updateTheme, 
    navItems, addNavItem, updateNavItem, deleteNavItem,
    news, addNews, updateNews, deleteNews,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addArtItem, updateArtItem, deleteArtItem,
    addTicket, updateTicket, deleteTicket
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isShaking, setIsShaking] = useState(false);
  const [activeSection, setActiveSection] = useState<string>('general');
  const [saveStatus, setSaveStatus] = useState<Record<string, boolean>>({});
  const [showPreview, setShowPreview] = useState(true);

  const [previewWidth, setPreviewWidth] = useState(window.innerWidth > 1400 ? 750 : 600);
  const [isResizing, setIsResizing] = useState(false);
  const [manualZoom, setManualZoom] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);

  const triggerSaveFeedback = (id: string) => {
    setSaveStatus({ ...saveStatus, [id]: true });
    setTimeout(() => setSaveStatus(prev => ({ ...prev, [id]: false })), 2000);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if(!login(loginIdentifier, loginPassword)) {
      setLoginError(true);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  };

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && containerRef.current) {
      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = containerRect.right - e.clientX;
      if (newWidth > 320 && newWidth < containerRect.width * 0.85) setPreviewWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  const getScaleFactor = () => {
    const desktopBaseWidth = 1280;
    const padding = 60; 
    const autoScale = (previewWidth - padding) / desktopBaseWidth;
    return Math.min(autoScale, 1.5) * manualZoom;
  };

  if (!isAdminOpen) return null;

  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4 animate-fade-in">
        <div className={`bg-white rounded-[2rem] w-full max-w-md shadow-2xl relative p-10 border border-slate-100 transition-transform ${isShaking ? 'animate-shake' : ''}`}>
          <button onClick={() => setIsAdminOpen(false)} className="absolute top-8 right-8 text-slate-300 hover:text-slate-600 p-1 transition-colors"><X className="w-5 h-5" /></button>
          <div className="text-center mb-10">
            <div className="w-16 h-16 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-center mx-auto mb-5 shadow-sm">
              <Landmark className="w-8 h-8 text-heritage-gold" />
            </div>
            <h2 className="text-2xl font-serif font-black text-slate-800 tracking-tight">{t.adminPortal[language]}</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em] mt-2">{t.cmsName[language]}</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Account ID</label>
              <input type="text" value={loginIdentifier} onChange={(e) => setLoginIdentifier(e.target.value)} className="input-field" placeholder="Username" required />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Security Key</label>
              <input type="password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} className="input-field" placeholder="Password" required />
            </div>
            <button type="submit" className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl hover:bg-slate-700 transition-all shadow-lg uppercase tracking-[0.2em] text-[10px] mt-4">Authorized Access</button>
          </form>
        </div>
      </div>
    );
  }

  const SectionTitle = ({ icon: Icon, title, subtitle }: any) => (
    <div className="mb-12">
      <div className="flex items-center gap-4 mb-3">
        <div className="bg-white border border-slate-200 p-2.5 rounded-2xl text-slate-400 shadow-sm"><Icon className="w-5 h-5" /></div>
        <h3 className="text-2xl font-serif font-black text-slate-800 tracking-tight">{title}</h3>
      </div>
      <div className="flex items-center gap-3">
        <div className="h-[1px] w-8 bg-heritage-gold/30"></div>
        <p className="text-[9px] text-slate-400 font-black uppercase tracking-[0.4em] leading-none">{subtitle}</p>
      </div>
    </div>
  );

  const SaveButton = ({ id }: { id: string }) => (
    <div className="flex justify-start mt-12 py-8 border-t border-slate-100">
      <button 
        onClick={() => triggerSaveFeedback(id)}
        className={`flex items-center gap-3 px-10 py-3 rounded-2xl font-black uppercase tracking-[0.2em] text-[10px] transition-all duration-300 border shadow-sm ${
          saveStatus[id] 
          ? 'bg-emerald-500 border-emerald-500 text-white' 
          : 'bg-white border-slate-200 text-slate-600 hover:border-heritage-gold hover:text-heritage-gold'
        }`}
      >
        {saveStatus[id] ? <CheckCircle className="w-4 h-4" /> : <Save className="w-4 h-4" />}
        {saveStatus[id] ? t.saved[language] : t.save[language]}
      </button>
    </div>
  );

  const sidebarLinks = [
    { id: 'general', label: 'Identitas', icon: Globe },
    { id: 'theme', label: 'Tampilan', icon: Palette },
    { id: 'navigation', label: 'Navigasi', icon: Navigation },
    { id: 'organization', label: 'Organisasi', icon: Users },
    { id: 'heritage', label: 'Warisan', icon: FileText },
    { id: 'arts', label: 'Kesenian', icon: Music },
    { id: 'news', label: 'Berita', icon: Instagram },
    { id: 'destinations', label: 'Destinasi', icon: MapPin },
    { id: 'tickets', label: 'Operasional', icon: Ticket },
    { id: 'contact', label: 'Kontak', icon: Phone },
  ];

  return (
    <div className="fixed inset-0 z-[100] flex bg-white font-sans overflow-hidden" ref={containerRef}>
      {/* Sidebar - White Minimalist */}
      <div className="w-72 bg-white border-r border-slate-100 flex flex-col h-full z-20">
        <div className="p-12 text-center">
          <div className="inline-flex bg-slate-50 border border-slate-100 text-heritage-gold p-3 rounded-2xl mb-5 shadow-sm">
            <Settings className="w-6 h-6" />
          </div>
          <h2 className="font-serif font-black text-lg tracking-tighter text-slate-800">DASHBOARD</h2>
          <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em] mt-1.5">Management Suite</p>
        </div>

        <nav className="flex-1 overflow-y-auto py-4 px-6 space-y-1.5 custom-scrollbar">
          {sidebarLinks.map((link) => (
            <button 
              key={link.id} 
              onClick={() => setActiveSection(link.id)} 
              className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all border ${
                activeSection === link.id 
                ? 'bg-slate-50 border-slate-200 text-slate-800 shadow-sm' 
                : 'bg-transparent border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50/50'
              }`}
            >
              <link.icon className={`w-4 h-4 ${activeSection === link.id ? 'text-heritage-gold' : 'opacity-40'}`} />
              {link.label}
              {activeSection === link.id && <div className="ml-auto w-1.5 h-1.5 bg-heritage-gold rounded-full shadow-[0_0_8px_#C5A059]"></div>}
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-slate-50">
          <button onClick={logout} className="w-full flex items-center justify-center gap-3 py-4 bg-slate-50 text-slate-400 border border-slate-100 rounded-2xl font-black text-[9px] uppercase tracking-widest hover:text-red-500 hover:border-red-100 hover:bg-red-50 transition-all">
            <Lock className="w-3.5 h-3.5" /> Sign Out
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full bg-[#FBFBFC] overflow-hidden">
        {/* Header - Transparent/White Blur */}
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 px-12 flex items-center justify-between z-10">
          <div className="flex items-center gap-6">
            <button onClick={() => setIsAdminOpen(false)} className="p-2.5 hover:bg-slate-50 rounded-xl border border-transparent hover:border-slate-200 transition-all"><ChevronLeft className="w-5 h-5 text-slate-400" /></button>
            <div className="h-6 w-[1px] bg-slate-100"></div>
            <h1 className="font-serif font-black text-xl text-slate-800 uppercase tracking-tighter">{activeSection}</h1>
          </div>
          <button onClick={() => setShowPreview(!showPreview)} className={`flex items-center gap-3 px-6 py-2.5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] transition-all border ${showPreview ? 'bg-slate-800 border-slate-800 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-400 hover:border-slate-800 hover:text-slate-800'}`}>
            {showPreview ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />} Preview Mode
          </button>
        </header>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 overflow-y-auto p-16 custom-scrollbar">
