          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-center mx-auto mb-5 shadow-sm">
              <Landmark className="w-8 h-8 text-heritage-gold" />
            </div>
            <h2 className="text-2xl font-serif font-black text-slate-800 tracking-tight">{t.adminPortal[language]}</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em] mt-2">{t.cmsName[language]}</p>
          </div>

          {/* Error Notification */}
          {loginError && (
             <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-3 animate-fade-in">
                <AlertTriangle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                <div>
                   <h4 className="text-[10px] font-black uppercase tracking-widest text-red-600 mb-1">Akses Ditolak</h4>
                   <p className="text-xs text-red-500 leading-relaxed">ID Akun atau Kunci Keamanan Anda salah. Silakan coba lagi.</p>
                </div>
             </div>
          )}

          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-1.5">
              <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${loginError ? 'text-red-400' : 'text-slate-400'}`}>Account ID</label>
              <input 
                type="text" 
                value={loginIdentifier} 
                onChange={(e) => handleInputChange(setLoginIdentifier, e.target.value)} 
                className={`input-field ${loginError ? '!border-red-200 !bg-red-50/30 text-red-600' : ''}`} 
                placeholder="Username" 
                required 
              />
            </div>
            <div className="space-y-1.5">
              <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${loginError ? 'text-red-400' : 'text-slate-400'}`}>Security Key</label>
              <input 
                type="password" 
                value={loginPassword} 
                onChange={(e) => handleInputChange(setLoginPassword, e.target.value)} 
                className={`input-field ${loginError ? '!border-red-200 !bg-red-50/30 text-red-600' : ''}`} 
                placeholder="Password" 
                required 
              />
            </div>
            <button type="submit" className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl hover:bg-slate-700 transition-all shadow-lg uppercase tracking-[0.2em] text-[10px] mt-4">Authorized Access</button>
          </form>
        </div>
      </div>
    );
  }

  const SectionTitle = ({ icon: Icon, title, subtitle }: any) => (
    <div className="mb-12">
      <div className="flex items-center gap-4 mb-3">
        <div className="bg-white border border-slate-200 p-2.5 rounded-2xl text-slate-400 shadow-sm"><Icon className="w-5 h-5" /></div>
