                    <div className="flex items-center gap-3">
                       <div className="p-2 bg-slate-50 border border-slate-100 rounded-xl text-slate-400"><Monitor className="w-4 h-4" /></div>
                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Preview Engine</span>
                    </div>

                    <div className="flex items-center gap-4 bg-slate-50 px-4 py-2 rounded-full border border-slate-100 shadow-sm">
