                       <div className="w-[1px] h-3 bg-slate-200 mx-1"></div>
                       <span className="text-[10px] font-mono font-black text-slate-800 w-12 text-center">{Math.round(getScaleFactor() * 100)}%</span>
                       <div className="w-[1px] h-3 bg-slate-200 mx-1"></div>
                       <button onClick={() => setManualZoom(prev => Math.min(prev + 0.1, 2.0))} className="text-slate-400 hover:text-slate-800 transition-colors"><ZoomIn className="w-4 h-4" /></button>
                    </div>
                </div>

                <div className="flex-1 w-full flex items-start justify-center overflow-auto custom-scrollbar p-16">
                   <div 
                     className="relative origin-top transition-transform duration-300 ease-out shadow-[0_40px_100px_rgba(0,0,0,0.08)] border border-slate-200/50 rounded-2xl" 
                     style={{ 
                        transform: `scale(${getScaleFactor()})`, 
                        width: '1280px', 
                        minHeight: '2000px',
                        marginTop: '20px'
                     }}
                   >
                     {/* MINIMALIST BROWSER FRAME */}
                     <div className="bg-white overflow-hidden flex flex-col h-full border border-slate-800 rounded-2xl shadow-2xl h-full">
                        <div className="h-12 bg-slate-800 flex items-center gap-4 px-6 shrink-0">
                           <div className="flex gap-2"><div className="w-2.5 h-2.5 bg-[#FF5F57] rounded-full" /><div className="w-2.5 h-2.5 bg-[#FEBC2E] rounded-full" /><div className="w-2.5 h-2.5 bg-[#28C840] rounded-full" /></div>
                           <div className="flex-1 bg-white/10 mx-6 rounded-md px-4 py-1.5 text-[9px] font-mono text-white/40 truncate flex items-center gap-3">
                              <Lock className="w-3 h-3 text-heritage-gold opacity-50" /> https://heritage.sawahlunto.go.id
                           </div>
                        </div>
                        <div className="flex-1 overflow-y-auto hide-scrollbar preview-content" style={{ '--color-primary': content.theme.primary, '--color-secondary': content.theme.secondary, '--color-background': content.theme.background, '--color-dark': content.theme.dark } as React.CSSProperties}>
                           <div className="pointer-events-none origin-top">
