                           </div>
                        </div>
                     </div>
                   </div>
                </div>

                <div className="sticky bottom-10 bg-white border border-slate-200 text-slate-400 px-6 py-3 rounded-full shadow-xl text-[9px] font-black uppercase tracking-[0.2em] flex items-center gap-3 opacity-90 transition-all cursor-default">
                   <GripHorizontal className="w-4 h-4 text-heritage-gold" /> Drag divider for dynamic scaling
                </div>
              </div>
            </>
          )}
        </div>
      </div>
      <style>{`
        .input-label { display: block; font-size: 0.6rem; font-weight: 900; color: #94A3B8; text-transform: uppercase; letter-spacing: 0.3em; margin-bottom: 0.75rem; }
        .input-field { width: 100%; background-color: #F8FAFC !important; border: 1.5px solid #F1F5F9; padding: 1.15rem 1.5rem; border-radius: 1.5rem; font-size: 0.85rem; color: #1E293B; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
        .input-field:focus { outline: none; border-color: #C5A059; background-color: #FFF !important; box-shadow: 0 10px 20px -10px rgba(197, 160, 89, 0.2); }
        .btn-add { background: #FFF; color: #475569; padding: 0.75rem 1.75rem; border-radius: 1.5rem; font-size: 0.65rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.2em; display: flex; align-items: center; gap: 0.5rem; transition: all 0.3s ease; border: 1.5px solid #F1F5F9; shadow-sm; }
        .btn-add:hover { background: #F1F5F9; border-color: #C5A059; color: #C5A059; transform: translateY(-2px); }
