import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useData } from '../contexts/DataContext';
import { 
  X, Plus, Trash2, Edit2, Globe, Palette, Users, FileText, Music, Instagram, 
  Phone, Ticket, MapPin, Navigation, Layout, User as UserIcon, Key, 
  AlertTriangle, Save, PlusCircle, ArrowUp, ArrowDown, Link as LinkIcon, 
  Image as ImageIcon, CheckCircle, Info, Landmark, Calendar, Clock, Camera,
  GripVertical, Eye, EyeOff, Monitor, ChevronLeft, ChevronRight, RefreshCw,
  GripHorizontal, Maximize, ZoomIn, ZoomOut, Lock, Settings, Target, Hash,
  Images, LogOut, ArrowLeft
} from 'lucide-react';

// Import public components for preview
import Hero from './Hero';
import HeritageMain from './HeritageMain';
import ArtsSection from './ArtsSection';
import Attractions from './Attractions';
import NewsSection from './NewsSection';
import InfoSection from './InfoSection';
import Footer from './Footer';
import MuseumMap from './MuseumMap';
import ExternalPortals from './ExternalPortals';

const t = {
  adminPortal: { en: 'Admin Portal', id: 'Portal Admin' },
  cmsName: { en: 'Sawahlunto Heritage CMS', id: 'CMS Warisan Sawahlunto' },
  save: { en: 'Save Changes', id: 'Simpan Perubahan' },
  saved: { en: 'Saved Successfully', id: 'Berhasil Disimpan' },
  cancel: { en: 'Cancel', id: 'Batal' },
  logout: { en: 'Logout', id: 'Keluar' },
};

const AdminPanel: React.FC = () => {
  const { 
    language, isAdminOpen, setIsAdminOpen, isAuthenticated, login, logout,
    content, updateContent, updateTheme, 
    navItems, addNavItem, updateNavItem, deleteNavItem,
    news, addNews, updateNews, deleteNews,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addArtItem, updateArtItem, deleteArtItem,
    addTicket, updateTicket, deleteTicket
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isShaking, setIsShaking] = useState(false);
  const [activeSection, setActiveSection] = useState<string>('general');
  const [saveStatus, setSaveStatus] = useState<Record<string, boolean>>({});
  const [showPreview, setShowPreview] = useState(true);

  const [previewWidth, setPreviewWidth] = useState(window.innerWidth > 1400 ? 750 : 600);
  const [isResizing, setIsResizing] = useState(false);
  const [manualZoom, setManualZoom] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);

  const triggerSaveFeedback = (id: string) => {
    setSaveStatus({ ...saveStatus, [id]: true });
    setTimeout(() => setSaveStatus(prev => ({ ...prev, [id]: false })), 2000);
  };

  const handleCancel = () => {
    setIsAdminOpen(false);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError(false);
    if(!login(loginIdentifier, loginPassword)) {
      setLoginError(true);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<string>>, value: string) => {
      setter(value);
      if (loginError) setLoginError(false);
  };

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && containerRef.current) {
      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = containerRect.right - e.clientX;
      if (newWidth > 320 && newWidth < containerRect.width * 0.85) setPreviewWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  const getScaleFactor = () => {
    const desktopBaseWidth = 1280;
    const padding = 60; 
    const autoScale = (previewWidth - padding) / desktopBaseWidth;
    return Math.min(autoScale, 1.5) * manualZoom;
  };

  if (!isAdminOpen) return null;

  // --- LOGIN SCREEN ---
  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#FBFBFC] p-4 animate-fade-in">
        {/* Background Decorative */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
           <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-heritage-gold/5 via-transparent to-transparent opacity-50"></div>
        </div>

        <div className={`bg-white rounded-[2.5rem] w-full max-w-md shadow-[0_20px_60px_-15px_rgba(0,0,0,0.05)] relative p-12 border border-slate-50 transition-transform ${isShaking ? 'animate-shake' : ''}`}>
          <button onClick={() => setIsAdminOpen(false)} className="absolute top-8 right-8 text-slate-300 hover:text-slate-600 p-2 transition-colors rounded-full hover:bg-slate-50"><X className="w-5 h-5" /></button>

          <div className="text-center mb-10">
            <div className="w-20 h-20 bg-slate-50 border border-slate-100 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm transform rotate-3">
              <Landmark className="w-8 h-8 text-heritage-gold" />
            </div>
            <h2 className="text-3xl font-serif font-bold text-slate-800 tracking-tight mb-2">{t.adminPortal[language]}</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em]">{t.cmsName[language]}</p>
          </div>

          {/* Error Notification */}
          {loginError && (
             <div className="mb-8 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-3 animate-fade-in">
                <AlertTriangle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                <div>
                   <h4 className="text-[11px] font-black uppercase tracking-widest text-red-600 mb-1">Akses Ditolak</h4>
                   <p className="text-xs text-red-500 leading-relaxed">ID Akun atau Kata Sandi tidak valid.</p>
                </div>
             </div>
          )}

          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-2">
              <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${loginError ? 'text-red-400' : 'text-slate-400'}`}>Account ID</label>
              <input 
                type="text" 
                value={loginIdentifier} 
                onChange={(e) => handleInputChange(setLoginIdentifier, e.target.value)} 
                className={`input-field ${loginError ? '!border-red-200 !bg-red-50/30 text-red-600' : ''}`} 
                placeholder="Username" 
                required 
              />
            </div>
            <div className="space-y-2">
              <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${loginError ? 'text-red-400' : 'text-slate-400'}`}>Security Key</label>
              <input 
                type="password" 
                value={loginPassword} 
                onChange={(e) => handleInputChange(setLoginPassword, e.target.value)} 
                className={`input-field ${loginError ? '!border-red-200 !bg-red-50/30 text-red-600' : ''}`} 
                placeholder="Password" 
                required 
              />
            </div>
            <button type="submit" className="w-full bg-slate-900 text-white font-black py-4.5 rounded-2xl hover:bg-heritage-gold transition-all shadow-lg hover:shadow-xl hover:-translate-y-1 uppercase tracking-[0.2em] text-[10px] mt-2">
                Masuk Portal
            </button>
          </form>
        </div>
      </div>
    );
  }

  // --- COMPONENT HELPERS ---

  const SectionHeader = ({ icon: Icon, title, subtitle }: any) => (
    <div className="mb-10">
      <div className="flex items-center gap-4 mb-3">
        <div className="bg-white border border-slate-200 p-3 rounded-2xl text-heritage-gold shadow-sm"><Icon className="w-6 h-6" /></div>
        <h3 className="text-3xl font-serif font-bold text-slate-800 tracking-tight">{title}</h3>
      </div>
      <div className="flex items-center gap-3 pl-1">
        <div className="h-[2px] w-8 bg-heritage-gold/30 rounded-full"></div>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] leading-none">{subtitle}</p>
      </div>
    </div>
  );

  const FormActions = ({ id, onCancel }: { id: string, onCancel?: () => void }) => (
    <div className="flex items-center justify-end gap-4 mt-12 pt-8 border-t border-slate-100">
      <button 
        onClick={onCancel || handleCancel}
        className="px-8 py-3 rounded-xl font-bold uppercase tracking-widest text-[10px] text-slate-400 hover:text-red-500 hover:bg-red-50 transition-colors"
      >
        {t.cancel[language]}
      </button>
      <button 
        onClick={() => triggerSaveFeedback(id)}
        className={`flex items-center gap-3 px-8 py-3 rounded-xl font-bold uppercase tracking-[0.2em] text-[10px] transition-all duration-300 shadow-md hover:shadow-lg hover:-translate-y-0.5 ${
          saveStatus[id] 
          ? 'bg-emerald-500 text-white cursor-default' 
          : 'bg-slate-900 text-white hover:bg-heritage-gold'
        }`}
      >
        {saveStatus[id] ? <CheckCircle className="w-4 h-4" /> : <Save className="w-4 h-4" />}
        {saveStatus[id] ? t.saved[language] : t.save[language]}
      </button>
    </div>
  );

  const sidebarLinks = [
    { id: 'general', label: 'Identitas', icon: Globe },
    { id: 'theme', label: 'Tampilan', icon: Palette },
    { id: 'navigation', label: 'Navigasi', icon: Navigation },
    { id: 'organization', label: 'Organisasi', icon: Users },
    { id: 'heritage', label: 'Warisan', icon: FileText },
    { id: 'arts', label: 'Kesenian', icon: Music },
    { id: 'news', label: 'Berita', icon: Instagram },
    { id: 'destinations', label: 'Destinasi', icon: MapPin },
    { id: 'tickets', label: 'Operasional', icon: Ticket },
    { id: 'contact', label: 'Kontak', icon: Phone },
  ];

  return (
    <div className="fixed inset-0 z-[100] flex bg-[#FBFBFC] font-sans overflow-hidden" ref={containerRef}>

      {/* Sidebar - Clean White */}
      <div className="w-72 bg-white border-r border-slate-100 flex flex-col h-full z-20 shadow-[4px_0_24px_rgba(0,0,0,0.02)]">
        <div className="p-10 pb-8 text-center border-b border-slate-50">
          <div className="inline-flex bg-slate-50 border border-slate-100 text-heritage-gold p-3.5 rounded-2xl mb-5 shadow-sm">
            <Settings className="w-6 h-6" />
          </div>
          <h2 className="font-serif font-black text-lg tracking-tight text-slate-800">DASHBOARD</h2>
          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-2">Management Suite</p>
        </div>

        <nav className="flex-1 overflow-y-auto py-6 px-5 space-y-1.5 custom-scrollbar">
          {sidebarLinks.map((link) => (
            <button 
              key={link.id} 
              onClick={() => setActiveSection(link.id)} 
              className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-[10px] font-bold uppercase tracking-[0.2em] transition-all duration-300 ${
                activeSection === link.id 
                ? 'bg-[#FBFBFC] text-heritage-gold shadow-sm border border-slate-100' 
                : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50 border border-transparent'
              }`}
            >
              <link.icon className={`w-4 h-4 ${activeSection === link.id ? 'text-heritage-gold' : 'opacity-40'}`} />
              {link.label}
              {activeSection === link.id && <div className="ml-auto w-1.5 h-1.5 bg-heritage-gold rounded-full shadow-[0_0_8px_#C5A059]"></div>}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-slate-50">
          <button onClick={logout} className="w-full flex items-center justify-center gap-3 py-4 bg-red-50 text-red-500 border border-red-100 rounded-2xl font-bold text-[10px] uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all duration-300">
            <LogOut className="w-3.5 h-3.5" /> Sign Out
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col h-full bg-[#FBFBFC] overflow-hidden relative">
        {/* Header Bar */}
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 px-10 flex items-center justify-between z-10 sticky top-0">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsAdminOpen(false)} className="p-2.5 bg-white border border-slate-200 rounded-xl text-slate-400 hover:border-slate-800 hover:text-slate-800 transition-all shadow-sm">
                <ArrowLeft className="w-4 h-4" />
             </button>
             <h1 className="font-serif font-bold text-lg text-slate-800 uppercase tracking-tight ml-2">{activeSection}</h1>
          </div>
          <button onClick={() => setShowPreview(!showPreview)} className={`flex items-center gap-3 px-5 py-2.5 rounded-full text-[9px] font-bold uppercase tracking-[0.2em] transition-all border shadow-sm ${showPreview ? 'bg-slate-800 border-slate-800 text-white' : 'bg-white border-slate-200 text-slate-500 hover:border-slate-800 hover:text-slate-800'}`}>
            {showPreview ? <Eye className="w-3.5 h-3.5" /> : <EyeOff className="w-3.5 h-3.5" />} Preview
          </button>
        </header>

        <div className="flex-1 flex overflow-hidden">
          {/* Scrollable Form Area */}
          <div className="flex-1 overflow-y-auto p-10 lg:p-14 custom-scrollbar">
            <div className="max-w-4xl mx-auto pb-20">

              {/* BRANDING EDITOR */}
              {activeSection === 'general' && (
                <div className="space-y-12 animate-fade-in">
                  <SectionHeader icon={Globe} title="Identitas Brand" subtitle="Aset Visual Utama" />

                  <div className="bg-white border border-slate-100 rounded-[2.5rem] p-12 shadow-[0_20px_50px_-12px_rgba(0,0,0,0.03)] space-y-10">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                      <div className="space-y-3">
                        <label className="input-label">Nama Situs</label>
                        <input type="text" value={content.branding.siteName} onChange={(e) => updateContent('branding', 'siteName', e.target.value)} className="input-field" />
                      </div>
                      <div className="space-y-3">
                        <label className="input-label">Slogan Platform</label>
                        <input type="text" value={content.branding.subTitle} onChange={(e) => updateContent('branding', 'subTitle', e.target.value)} className="input-field" />
                      </div>
