                    <div className="space-y-4 pt-8 border-t border-slate-50">
                        <label className="input-label">Logo Korporat (URL Gambar)</label>
                        <div className="flex gap-8 items-start">
                          <div className="flex-1 space-y-2">
                             <input type="text" value={content.branding.logoUrl} onChange={(e) => updateContent('branding', 'logoUrl', e.target.value)} className="input-field font-mono text-xs" placeholder="https://..." />
                             <p className="text-[10px] text-slate-400 pl-2">Rekurensi format: PNG / SVG Transparent</p>
                          </div>
                          <div className="w-24 h-24 bg-[#FBFBFC] rounded-[1.5rem] border border-slate-100 flex items-center justify-center overflow-hidden shrink-0 shadow-inner">
                            {content.branding.logoUrl ? <img src={content.branding.logoUrl} alt="Logo" className="max-w-full max-h-full object-contain p-4" /> : <ImageIcon className="w-6 h-6 text-slate-300" />}
                          </div>
                        </div>
                    </div>

                    <FormActions id="branding" />
                  </div>
                </div>
              )}

              {/* NEWS EDITOR */}
              {activeSection === 'news' && (
                <div className="space-y-12 animate-fade-in">
                   <div className="flex justify-between items-end border-b border-slate-200/60 pb-10">
                      <SectionHeader icon={Instagram} title="Media & Artikel" subtitle="Distribusi Konten" />
                      <button onClick={() => addNews({ id: Date.now().toString(), date: new Date().toISOString().split('T')[0], title: {en:'New Article', id:'Berita Baru'}, summary: {en:'',id:''}, content: {en:'',id:''}, imageUrl: 'https://picsum.photos/400/300', imageUrls: [] })} className="btn-add"><Plus className="w-4 h-4" /> Tambah Artikel</button>
                   </div>

                   <div className="space-y-8">
                      {news.map(item => (
                        <div key={item.id} className="bg-white border border-slate-100 rounded-[2.5rem] p-10 shadow-[0_10px_40px_-10px_rgba(0,0,0,0.03)] space-y-8 hover:shadow-lg transition-all duration-500 relative group/card">
                           <div className="absolute top-8 right-8 z-10">
                             <button onClick={() => deleteNews(item.id)} className="p-3 bg-white border border-slate-100 rounded-2xl text-slate-300 hover:text-red-500 hover:bg-red-50 hover:border-red-100 transition-all shadow-sm"><Trash2 className="w-4 h-4" /></button>
                           </div>

