import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useData } from '../contexts/DataContext';
import { 
  X, Plus, Trash2, Edit2, Globe, Palette, Users, FileText, Music, Instagram, 
  Phone, Ticket, MapPin, Navigation, Layout, User as UserIcon, Key, 
  AlertTriangle, Save, PlusCircle, ArrowUp, ArrowDown, Link as LinkIcon, 
  Image as ImageIcon, CheckCircle, Info, Landmark, Calendar, Clock, Camera,
  GripVertical, Eye, EyeOff, Monitor, ChevronLeft, ChevronRight, RefreshCw,
  GripHorizontal, Maximize, ZoomIn, ZoomOut, Lock, Settings, Target, Hash,
  Images, LogOut, ArrowLeft, Layers, Map as MapIcon, MousePointerClick
} from 'lucide-react';

// Import public components for preview
import Hero from './Hero';
import HeritageMain from './HeritageMain';
import ArtsSection from './ArtsSection';
import Attractions from './Attractions';
import NewsSection from './NewsSection';
import InfoSection from './InfoSection';
import Footer from './Footer';
import MuseumMap from './MuseumMap';
import ExternalPortals from './ExternalPortals';

const t = {
  adminPortal: { en: 'Admin Portal', id: 'Portal Admin' },
  cmsName: { en: 'Sawahlunto Heritage CMS', id: 'CMS Warisan Sawahlunto' },
  save: { en: 'Save Changes', id: 'Simpan Perubahan' },
  saved: { en: 'Saved Successfully', id: 'Berhasil Disimpan' },
  cancel: { en: 'Cancel', id: 'Batal' },
  logout: { en: 'Logout', id: 'Keluar' },
};

const AdminPanel: React.FC = () => {
  const { 
    language, isAdminOpen, setIsAdminOpen, isAuthenticated, login, logout,
    content, updateContent, updateTheme, 
    navItems, addNavItem, updateNavItem, deleteNavItem,
    news, addNews, updateNews, deleteNews,
    attractions, addAttraction, updateAttraction, deleteAttraction,
    addArtItem, updateArtItem, deleteArtItem,
    addTicket, updateTicket, deleteTicket,
    addHeroSlide, updateHeroSlide, deleteHeroSlide,
    museums, addMuseum, updateMuseum, deleteMuseum,
    socialLinks, addSocialLink, updateSocialLink, deleteSocialLink,
    externalLinks, addExternalLink, updateExternalLink, deleteExternalLink
  } = useData();

  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isShaking, setIsShaking] = useState(false);
  const [activeSection, setActiveSection] = useState<string>('general');
  const [saveStatus, setSaveStatus] = useState<Record<string, boolean>>({});
  const [showPreview, setShowPreview] = useState(true);

  const [previewWidth, setPreviewWidth] = useState(window.innerWidth > 1400 ? 750 : 600);
  const [isResizing, setIsResizing] = useState(false);
  const [manualZoom, setManualZoom] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);

  const triggerSaveFeedback = (id: string) => {
    setSaveStatus({ ...saveStatus, [id]: true });
    setTimeout(() => setSaveStatus(prev => ({ ...prev, [id]: false })), 2000);
  };

  const handleCancel = () => {
    setIsAdminOpen(false);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError(false);
    if(!login(loginIdentifier, loginPassword)) {
      setLoginError(true);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<string>>, value: string) => {
      setter(value);
      if (loginError) setLoginError(false);
  };

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && containerRef.current) {
      const containerRect = containerRef.current.getBoundingClientRect();
      const newWidth = containerRect.right - e.clientX;
      if (newWidth > 320 && newWidth < containerRect.width * 0.85) setPreviewWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  const getScaleFactor = () => {
    const desktopBaseWidth = 1280;
    const padding = 60; 
    const autoScale = (previewWidth - padding) / desktopBaseWidth;
    return Math.min(autoScale, 1.5) * manualZoom;
  };

  if (!isAdminOpen) return null;

  // --- LOGIN SCREEN ---
  if (!isAuthenticated) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#FBFBFC] p-4 animate-fade-in">
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
           <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-heritage-gold/5 via-transparent to-transparent opacity-50"></div>
        </div>

        <div className={`bg-white rounded-[2.5rem] w-full max-w-md shadow-[0_20px_60px_-15px_rgba(0,0,0,0.05)] relative p-12 border border-slate-50 transition-transform ${isShaking ? 'animate-shake' : ''}`}>
          <button onClick={() => setIsAdminOpen(false)} className="absolute top-8 right-8 text-slate-300 hover:text-slate-600 p-2 transition-colors rounded-full hover:bg-slate-50"><X className="w-5 h-5" /></button>

          <div className="text-center mb-10">
            <div className="w-20 h-20 bg-slate-50 border border-slate-100 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm transform rotate-3">
              <Landmark className="w-8 h-8 text-heritage-gold" />
            </div>
            <h2 className="text-3xl font-serif font-bold text-slate-800 tracking-tight mb-2">{t.adminPortal[language]}</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em]">{t.cmsName[language]}</p>
          </div>

          {loginError && (
             <div className="mb-8 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-3 animate-fade-in">
                <AlertTriangle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                <div>
                   <h4 className="text-[11px] font-black uppercase tracking-widest text-red-600 mb-1">Akses Ditolak</h4>
                   <p className="text-xs text-red-500 leading-relaxed">ID Akun atau Kata Sandi tidak valid.</p>
                </div>
             </div>
          )}

